from optimum.nvidia.lang import DataType


def as_numpy(x: torch.Tensor, dtype: DataType) -> np.array:
    x = x.to(dtype.as_torch())

    if dtype != DataType.BFLOAT16:
        x_ = x.cpu().numpy()
    else:
        x_ = x.view(torch.int16).cpu().numpy()
    return x_.view(dtype.as_numpy())


