from typing import Optional

from tensorrt_llm._torch.models.modeling_utils import MODEL_CLASS_MAPPER_MAPPING


class AutoCheckpointMapper():

    @staticmethod
    def get(format: str, name: Optional[str] = None) -> "BaseWeightMapper":
        if name is not None:
            try:
                return MODEL_CLASS_MAPPER_MAPPING[f'{name}_{format}']()
            except KeyError:  # no mapper for this model architecture, resort to default
                # TODO smor- a potential bug here, if the class isn't added to __init__, it will return the default mapper
                return MODEL_CLASS_MAPPER_MAPPING[format]()
        else:
            return MODEL_CLASS_MAPPER_MAPPING[format]()

"""Backend that uses torch.compile only."""

import torch
import torch.nn as nn

from tensorrt_llm._torch.auto_deploy.utils.logger import ad_logger

from ..compiler import BackendCompiler, BackendRegistry


@BackendRegistry.register("torch-compile")
class TorchCompileCompiler(BackendCompiler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        ad_logger.info(f"Torch Dynamo cache size limit {torch._dynamo.config.cache_size_limit=}")

    def compile(self) -> nn.Module:
        """Compile the model using torch.compile."""
        return torch.compile(self.gm, dynamic=True)

"""Mixed backend with torch.compile + Cudagraph."""

import torch

from tensorrt_llm._torch.auto_deploy.utils.logger import ad_logger

from ..compiler import BackendRegistry
from .torch_cudagraph import CapturedGraph, TorchCudagraphCompiler


@BackendRegistry.register("torch-opt")
class TorchOptCompiler(TorchCudagraphCompiler):
    """Compiler that uses both torch.compile and CUDA graphs."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        torch._dynamo.config.recompile_limit = max(
            len(self.cuda_graph_batch_sizes), torch._dynamo.config.recompile_limit
        )
        ad_logger.info(
            f"Setting Torch Dynamo recompile limit {torch._dynamo.config.recompile_limit=}; "
            f"{torch._dynamo.config.cache_size_limit=}"
        )

    def _init_captured_graph(self, gm, in_spec, out_spec) -> CapturedGraph:
        gm = torch.compile(gm, dynamic=True)
        return super()._init_captured_graph(gm, in_spec, out_spec)

from tensorrt_llm._torch.models.checkpoints.hf.weight_mapper import \
    HfWeightMapper
from tensorrt_llm._torch.models.modeling_utils import register_mapper


@register_mapper("HF", "Llama4ForConditionalGeneration")
class Llama4HfWeightMapper(HfWeightMapper):
    """
    Weight mapper for Llama4ForConditionalGeneration that handles the
    'language_model.' prefix removal from weight keys.
    """

    def filter_weights(self, prefix: str, weights: dict) -> dict:
        transformed_weights = {}
        for key, value in weights.items():
            if key.startswith("language_model."):
                new_key = key[len("language_model."):]
                transformed_weights[new_key] = value
            else:
                transformed_weights[key] = value

        return super().filter_weights(prefix, transformed_weights)

from torch import nn

from tensorrt_llm._torch.models.checkpoints.base_weight_mapper import \
    BaseWeightMapper
from tensorrt_llm._torch.models.modeling_utils import register_mapper


@register_mapper("HF", "MixtralForCausalLM")
class MixtralHfWeightMapper(BaseWeightMapper):

    def map_weights(self) -> None:
        self.mapping.update({
            'qkv_proj': ['q_proj', 'k_proj', 'v_proj'],
        })

    def apply_callbacks(self, module: nn.Module, module_name: str,
                        module_names_breakdown: list[str],
                        weights: dict) -> list[dict]:
        module_weights = []

        for new_name in self.mapping[module_name]:
            fw = self.filter_weights(
                '.'.join(module_names_breakdown + [new_name]), weights)
            module_weights.append(fw)

        return module_weights

#!/usr/bin/env python3
import os

import click

from tensorrt_llm.hlapi import LLM, ModelConfig, SamplingConfig


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, required=True)
@click.option("--engine_dir", type=str, default=None)
def main(model_dir: str, tp_size: int, engine_dir: str):
    config = ModelConfig(model_dir)
    config.parallel_config.tp_size = tp_size

    llm = LLM(config)

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    prompt = [45, 12, 13]
    sampling_config = SamplingConfig(max_new_tokens=10)
    for output in llm.generate([prompt], sampling_config=sampling_config):
        print(output)


if __name__ == '__main__':
    main()

from tensorrt_llm.llmapi import LLM
from tensorrt_llm.llmapi.utils import (download_hf_model,
                                       download_hf_pretrained_config)

try:
    from test_llm import llama_model_path
except ImportError:
    from .test_llm import llama_model_path

prompts = ["A B C"]

model_name = "TinyLlama/TinyLlama-1.1B-Chat-v1.0"


def test_llm_with_model_downloaded():
    llm = LLM(model=model_name, enable_build_cache=True)
    for output in llm.generate(prompts):
        print(output)


def test_llm_with_tokenizer_downloaded():
    llm = LLM(model=llama_model_path, tokenizer=model_name)
    for output in llm.generate(prompts):
        print(output)


def test_download_config():
    path0 = download_hf_pretrained_config(model_name)
    print(f"download config to {path0}")
    path1 = download_hf_model(model_name)
    print(f"download model to {path1}")
    assert path0 == path1


if __name__ == "__main__":
    test_download_config()
    test_llm_with_model_downloaded()

import os
from typing import Literal

import click

from tensorrt_llm.llmapi.mpi_session import RemoteMpiCommSessionClient
from tensorrt_llm.llmapi.utils import print_colored


@click.command()
@click.option("--task_type",
              type=click.Choice(["submit", "submit_sync"]),
              default="submit")
def main(task_type: Literal["submit", "submit_sync"]):
    tasks = [0]
    assert os.environ[
        'TLLM_SPAWN_PROXY_PROCESS_IPC_ADDR'] is not None, "TLLM_SPAWN_PROXY_PROCESS_IPC_ADDR is not set"
    client = RemoteMpiCommSessionClient(
        os.environ['TLLM_SPAWN_PROXY_PROCESS_IPC_ADDR'])
    for task in tasks:
        if task_type == "submit":
            client.submit(print_colored, f"{task}\n", "green")
        elif task_type == "submit_sync":
            res = client.submit_sync(print_colored, f"{task}\n", "green")
            print(res)


if __name__ == "__main__":
    main()

"""Unit tests for custom dist ops."""

import pytest
import torch
from _dist_test_utils import get_device_counts

from tensorrt_llm._torch.auto_deploy.distributed.common import spawn_multiprocess_job


def _run_all_reduce_test(rank, world_size):
    x = torch.ones(10, 10).to("cuda")
    y = torch.ops.auto_deploy.torch_dist_all_reduce(x)

    assert torch.equal(x * world_size, y)


def _run_all_gather_test(rank, world_size):
    x = torch.ones(10, 10).to("cuda")
    y = torch.ops.auto_deploy.torch_dist_all_gather(x)

    assert torch.sum(y) == world_size * torch.sum(x)
    assert y.shape == (world_size * x.shape[0], *x.shape[1:])


@pytest.mark.parametrize("device_count", get_device_counts())
def test_all_reduce(device_count):
    spawn_multiprocess_job(job=_run_all_reduce_test, size=device_count)


@pytest.mark.parametrize("device_count", get_device_counts())
def test_all_gather(device_count):
    spawn_multiprocess_job(job=_run_all_gather_test, size=device_count)

