from torch import nn

from tensorrt_llm._torch.models.checkpoints.hf.weight_mapper import \
    HfWeightMapper
from tensorrt_llm._torch.models.modeling_utils import register_mapper
from tensorrt_llm._torch.modules.fused_moe.interface import MoE


@register_mapper("HF", "Qwen2MoeForCausalLM")
class Qwen2MoeHfWeightMapper(HfWeightMapper):

    def is_special_instance_module(self, module: nn.Module) -> bool:
        return isinstance(module, MoE)

    def handle_special_instance_module(self, module: nn.Module,
                                       module_name: str,
                                       module_weights: dict) -> None:
        if isinstance(module, MoE):
            updated_module_weights = {}
            for weight_name, weight_value in module_weights.items():
                new_weight_name = weight_name.replace(
                    "gate_proj", "w1").replace("up_proj",
                                               "w3").replace("down_proj", "w2")
                updated_module_weights[new_weight_name] = weight_value
            del module_weights
            module.load_weights(weights=[updated_module_weights])

#!/usr/bin/env python
from mpi4py.futures import MPICommExecutor

from tensorrt_llm._utils import mpi_comm, mpi_rank, mpi_world_size
from tensorrt_llm.hlapi.mpi_session import MpiCommSession, MPINodeState


class MpiTask:

    def __init__(self):
        self.executor = MpiCommSession(n_workers=4)

    @staticmethod
    def task():
        if MPINodeState.state is None:
            MPINodeState.state = 0

        MPINodeState.state += 1
        print(f"rank: {mpi_rank()}, state: {MPINodeState.state}")

        return (mpi_rank(), MPINodeState.state)

    def run(self):
        results = self.executor.submit_sync(MpiTask.task)
        results = sorted(results, key=lambda x: x[0])
        assert results == [(i, 1) for i in range(mpi_world_size())], results


def main():
    # The root node
    if mpi_rank() == 0:
        the_task = MpiTask()
        the_task.run()

    else:  # The worker node
        with MPICommExecutor(mpi_comm()) as executor:
            pass


if __name__ == '__main__':
    main()

