import logging
from contextlib import asynccontextmanager
from typing import AsyncGenerator, Optional

from tensorrt_llm import LLM

logging.basicConfig(level=logging.DEBUG)


class TensorRTLLMEngine:
    def __init__(self, engine_args):
        self.engine_args = engine_args
        self._llm: Optional[LLM] = None

    async def initialize(self):
        if not self._llm:
            model = self.engine_args.pop("model")
            self._llm = LLM(
                model=model,
                **self.engine_args,
            )

    async def cleanup(self):
        if self._llm:
            try:
                self._llm.shutdown()
            except Exception as e:
                logging.error(f"Error during cleanup: {e}")
            finally:
                self._llm = None

    @property
    def llm(self):
        if not self._llm:
            raise RuntimeError("Engine not initialized")
        return self._llm


@asynccontextmanager
async def get_llm_engine(engine_args) -> AsyncGenerator[TensorRTLLMEngine, None]:
    engine = TensorRTLLMEngine(engine_args)
    try:
        await engine.initialize()
        yield engine
    except Exception as e:
        logging.error(f"Error in engine context: {e}")
        raise
    finally:
        await engine.cleanup()

import inspect

from tensorrt_llm import Builder


class BuilderPatcher:
    # TODO: Remove this once available natively in TensorRT-LLM - `optimize(network)` lowers predictive performance for Whisper.

    def __init__(self):
        self.builder_path = inspect.getfile(Builder)

    def __enter__(self):
        with open(self.builder_path, "r") as file:
            lines = file.readlines()

        for i in range(len(lines)):
            if (
                i > 0
                and lines[i] == "    optimize(network)\n"
                and "# PATCHED" not in lines[i - 1]
            ):
                lines[i] = (
                    "    if getattr(model.config, 'optimize_network', True):\n        # PATCHED\n        optimize(network)\n    else:\n        logger.info('Network optimization disabled during build.')\n"
                )

        with open(self.builder_path, "w") as f:
            f.writelines(lines)

    def __exit__(self, exc_type, exc_value, traceback):
        with open(self.builder_path, "r") as file:
            lines = file.readlines()

        for i in range(len(lines)):
            if lines[i] == "        optimize(network)\n":
                lines[i - 1] = ""
                lines[i - 2] = ""
                lines[i] = "    optimize(network)\n"
                lines[i + 1] = ""
                lines[i + 2] = ""

        with open(self.builder_path, "w") as f:
            f.writelines(lines)

