import argparse
from typing import List
from tensorrt_llm.sampling_params import SamplingParams, LogitsProcessor


class TRTLLMTester:
    def __init__(self, model_name: str = "Qwen/Qwen2.5-1.5B-Instruct"):
        # Temporarily attempt to import the torch backend until it becomes default
        try:
            from tensorrt_llm._torch import LLM
        except ImportError:
            from tensorrt_llm import LLM

        self.llm = LLM(model=model_name)

    def run(self, prompts: List[str], max_tokens: int = 256, logits_processor: LogitsProcessor = None):
        sparams = {"top_k": 1, "max_tokens": max_tokens, "temperature": 0.001}
        if logits_processor:
            sparams["logits_processor"] = logits_processor

        prompts_with_template = []
        for prompt in prompts:
            messages = [
                {
                    "role": "user",
                    "content": prompt
                }
            ]
            text = self.llm.tokenizer.apply_chat_template(messages, tokenize=False, add_generation_prompt=True)
            prompts_with_template.append(text)

        gens = self.llm.generate(prompts_with_template, SamplingParams(**sparams))
        for prompt, gen in zip(prompts, gens):
            print(prompt)
            print(gen.outputs[0].text)


def get_parser():
    parser = argparse.ArgumentParser(description="Logits Processor Example")
    parser.add_argument("--model_name",
                        "-m",
                        type=str,
                        default="Qwen/Qwen2.5-1.5B-Instruct",
                        help="Directory or HF link containing model")
    parser.add_argument("--prompt",
                        "-p",
                        type=str,
                        default="Please give me information about macaques:",
                        help="Prompt to test")

    return parser.parse_args()

import asyncio
import json
from typing import List

from tensorrt_llm.scaffolding import TaskStatus, Worker

from .mcp_task import MCPCallTask, MCPListTask
from .mcp_utils import MCPClient


class MCPWorker(Worker):

    def __init__(
        self,
        mcp_clients: List,
    ):
        self.mcp_clients = mcp_clients

    @classmethod
    async def init_with_urls(cls, urls):
        clients = []
        for url in urls:
            client = MCPClient()
            await client.connect_to_sse_server(server_url=url)
            clients.append(client)
        return cls(clients)

    async def call_handler(self, task: MCPCallTask) -> TaskStatus:
        for mcp_client in self.mcp_clients:
            response = await mcp_client.list_tools()
            for tool in response.tools:
                if task.tool_name not in tool.name:
                    continue
                print(f"\ncall handler {tool.name} and {task.tool_name}\n")
                tool_name = task.tool_name
                args = json.loads(task.args)
                response = await mcp_client.call_tool(tool_name, args)
                task.output_str = response.content[0].text
                return TaskStatus.SUCCESS

    async def list_handler(self, task: MCPListTask) -> TaskStatus:
        result_tools = []
        for mcp_client in self.mcp_clients:
            response = await mcp_client.list_tools()
            result_tools.extend(response.tools)
        task.result_tools = result_tools
        return TaskStatus.SUCCESS

    def shutdown(self):
        loop = asyncio.get_event_loop()
        for mcp_client in self.mcp_clients:
            if loop.is_running():
                asyncio.run_coroutine_threadsafe(mcp_client.cleanup(), loop)
            else:
                loop.run_until_complete(self.mcp_client.cleanup())

    task_handlers = {MCPListTask: list_handler, MCPCallTask: call_handler}

import unittest

import torch

from tensorrt_llm.layers import GroupNorm
from tensorrt_llm.module import Module, ModuleList


class Module1(Module):

    def __init__(self, name):
        super(Module1, self).__init__()
        self.name = name

    def forward(self):
        self.register_network_output('o1', 1)


class Module2(Module):

    def __init__(self):
        super(Module2, self).__init__()
        self.name = 'module2'
        self.m1 = Module1('m1')
        self.m2 = Module1('m2')

    def forward(self):
        self.m1.forward()
        self.m2.forward()
        self.register_network_output('o2', 2)
        self.register_network_output('o3', 3)


class Module3(Module):

    def __init__(self):
        super(Module3, self).__init__()
        self.name = 'module3'
        self.m1 = Module2()

    def forward(self):
        self.m1.forward()
        self.register_network_output('o4', 4)


class Module4(Module):

    def __init__(self):
        super(Module4, self).__init__()
        self.layers = ModuleList([Module2(), Module2()])

    def forward(self):
        for l in self.layers:
            l.forward()


class TestModule(unittest.TestCase):

    def test_module(self):
        m = Module3()
        m.forward()

        self.assertEqual(4, len(list(m.named_modules())))
        self.assertEqual(5, len(list(m.named_network_outputs())))

    def test_module_list(self):
        m = Module4()
        m.forward()

        self.assertEqual(8, len(list(m.named_modules())))
        self.assertEqual(8, len(list(m.named_network_outputs())))

    def test_module_named_parameter(self):
        m = GroupNorm(2, 4)
        md = {k: v for k, v in m.named_parameters()}

        tm = torch.nn.GroupNorm(2, 4)
        tmd = {k: v for k, v in tm.named_parameters()}

        self.assertEqual(len(md), len(tmd))

        for k, _ in md.items():
            self.assertIn(k, tmd)

        for k, _ in tmd.items():
            self.assertIn(k, md)

import pytest

from tensorrt_llm.tools.plugin_gen.core import InputArg, Type
from tensorrt_llm.tools.plugin_gen.shape_infer import *


@pytest.mark.parametrize('expr', [
    "a[m,n,k]:m*2+k+(n+1) -> b",
    "a[m,n,k] -> b[m*n+k, 2*k, (3+1) * k]",
    "a[*] -> b[*]",
    "Q[m,n,k,*] : m -> batch_size",
])
def test_ToAst(expr: str):
    ast = parser.parse(expr)
    ast = ToAst()(ast)
    assert ast

    if isinstance(ast, DeduceDimSizeArgRule):
        assert ast.left
        assert ast.expr
        assert ast.right


@pytest.mark.parametrize('expr, target', [
    ("a[m,n,k]:m*2+k+(n+1) -> b",
     "((inputDesc[0].dims.d[0] * 2) + (inputDesc[0].dims.d[2] + (inputDesc[0].dims.d[1] + 1)))"
     ),
    ("a[m,n,k]:m*(2+k)+n+1 -> b",
     "((inputDesc[0].dims.d[0] * (2 + inputDesc[0].dims.d[2])) + (inputDesc[0].dims.d[1] + 1))"
     ),
    ("a[m,n,k] -> b[m*((((n+1))))]", """
if (outputIndex == 0) {
  outputDims.nbDims = 1;
  outputDims.d[0] = (inputDims[0].d[0] * (inputDims[0].d[1] + 1));
}
     """),
    ("a[m,n,k] -> b[m*(n+k), 2*n, k+3]", """
nvinfer1::DimsExprs outputDims;
if (outputIndex == 0) {
  outputDims.nbDims = 3;
  outputDims.d[0] = (inputDims[0].d[0] * (inputDims[0].d[1] + inputDims[0].d[2]));
  outputDims.d[1] = (2 * inputDims[0].d[1]);
  outputDims.d[2] = (inputDims[0].d[2] + 3);
}""")
])
def test_CppCodeTranspiler(expr: str, target: str):
    args = dict(
        a=InputArg('a', Type('fp16')),
        b=InputArg('b', Type('fp16')),
    )
    target = target.strip()

    transpiler = CppCodeTranspiler(args)

    shape_infer_code, dim_infer_code = transpiler([expr])

    # we don't check the correctness of the code since the lark produces unstable ast tree
    # refer to https://github.com/lark-parser/lark/issues/324
    assert shape_infer_code or dim_infer_code

#!/usr/bin/env python3
import os
from typing import Optional

import click

from tensorrt_llm import LLM as TorchLLM
from tensorrt_llm._tensorrt_engine import LLM
from tensorrt_llm.llmapi import KvCacheConfig, SamplingParams


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, required=True)
@click.option("--engine_dir", type=str, default=None)
@click.option("--n", type=int, default=1)
@click.option("--best_of", type=int, default=None)
@click.option("--top_k", type=int, default=1)
@click.option("--use_beam_search", is_flag=True)
@click.option("--use_pytorch", is_flag=True)
def main(model_dir: str, tp_size: int, engine_dir: Optional[str], n: int,
         best_of: Optional[int], top_k: int, use_beam_search: bool,
         use_pytorch: bool):
    if use_pytorch:
        llm = TorchLLM(
            model_dir,
            tensor_parallel_size=tp_size,
            kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))
    else:
        llm = LLM(model_dir,
                  tensor_parallel_size=tp_size,
                  kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4))

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10,
                                     end_id=-1,
                                     n=n,
                                     best_of=best_of,
                                     use_beam_search=use_beam_search,
                                     top_k=top_k)
    print(sampling_params)
    prompt_token_ids = [45, 12, 13]
    for output in llm.generate([prompt_token_ids],
                               sampling_params=sampling_params):
        print(output)

    print("run_llm.py Done")


if __name__ == '__main__':
    main()

import pytest

from tensorrt_llm.tools.plugin_gen.core import InputArg, Type
from tensorrt_llm.tools.plugin_gen.shape_infer import *


@pytest.mark.parametrize('expr', [
    "a[m,n,k]:m*2+k+(n+1) -> b",
    "a[m,n,k] -> b[m*n+k, 2*k, (3+1) * k]",
    "a[*] -> b[*]",
    "Q[m,n,k,*] : m -> batch_size",
    "a[b, l, h] -> b[b, h, l /// 256, 256]",
    "a[b, l, h] -> b[b, h, l /// 256, headsize]",
    "b[b, l, h]: l -> seqlen",
])
def test_ToAst(expr: str):
    ast = parser.parse(expr)
    ast = ToAst()(ast)
    assert ast

    if isinstance(ast, DeduceDimSizeArgRule):
        assert ast.left
        assert ast.expr
        assert ast.right


@pytest.mark.parametrize('expr, target', [
    ("a[m,n,k]:m*2+k+(n+1) -> b",
     "((inputDesc[0].dims.d[0] * 2) + (inputDesc[0].dims.d[2] + (inputDesc[0].dims.d[1] + 1)))"
     ),
    ("a[m,n,k]:m*(2+k)+n+1 -> b",
     "((inputDesc[0].dims.d[0] * (2 + inputDesc[0].dims.d[2])) + (inputDesc[0].dims.d[1] + 1))"
     ),
    ("a[m,n,k] -> b[m*((((n+1))))]", """
if (outputIndex == 0) {
  outputDims.nbDims = 1;
  outputDims.d[0] = (inputDims[0].d[0] * (inputDims[0].d[1] + 1));
}
     """),
    ("a[m,n,k] -> b[m*(n+k), 2*n, k+3]", """
nvinfer1::DimsExprs outputDims;
if (outputIndex == 0) {
  outputDims.nbDims = 3;
  outputDims.d[0] = (inputDims[0].d[0] * (inputDims[0].d[1] + inputDims[0].d[2]));
  outputDims.d[1] = (2 * inputDims[0].d[1]);
  outputDims.d[2] = (inputDims[0].d[2] + 3);
}""")
])
def test_CppCodeTranspiler(expr: str, target: str):
    args = dict(
        a=InputArg('a', Type('fp16')),
        b=InputArg('b', Type('fp16')),
    )
    target = target.strip()

    transpiler = CppCodeTranspiler(args)

    shape_infer_code, dim_infer_code = transpiler([expr])

    # we don't check the correctness of the code since the lark produces unstable ast tree
    # refer to https://github.com/lark-parser/lark/issues/324
    assert shape_infer_code or dim_infer_code

import unittest

import torch

from tensorrt_llm.layers import GroupNorm
from tensorrt_llm.module import Module, ModuleList


class Module1(Module):

    def __init__(self, name):
        super(Module1, self).__init__()
        self.name = name

    def forward(self):
        self.register_network_output('o1', 1)


class Module2(Module):

    def __init__(self):
        super(Module2, self).__init__()
        self.name = 'module2'
        self.m1 = Module1('m1')
        self.m2 = Module1('m2')

    def forward(self):
        self.m1.forward()
        self.m2.forward()
        self.register_network_output('o2', 2)
        self.register_network_output('o3', 3)


class Module3(Module):

    def __init__(self):
        super(Module3, self).__init__()
        self.name = 'module3'
        self.m1 = Module2()

    def forward(self):
        self.m1.forward()
        self.register_network_output('o4', 4)


class Module4(Module):

    def __init__(self):
        super(Module4, self).__init__()
        self.layers = ModuleList([Module2(), Module2()])

    def forward(self):
        for l in self.layers:
            l.forward()


class TestModule(unittest.TestCase):

    def test_module(self):
        m = Module3()
        m.forward()

        self.assertEqual(4, len(list(m.named_modules())))
        self.assertEqual(5, len(list(m.named_network_outputs())))

    def test_module_list(self):
        m = Module4()
        m.forward()

        self.assertEqual(8, len(list(m.named_modules())))
        self.assertEqual(8, len(list(m.named_network_outputs())))

    def test_module_named_parameter(self):
        m = GroupNorm(2, 4)
        md = {k: v for k, v in m.named_parameters()}

        tm = torch.nn.GroupNorm(2, 4)
        tmd = {k: v for k, v in tm.named_parameters()}

        self.assertEqual(len(md), len(tmd))

        for k, _ in md.items():
            self.assertIn(k, tmd)

        for k, _ in tmd.items():
            self.assertIn(k, md)

