import os
from functools import wraps
from typing import Callable, Optional

from tensorrt_llm.logger import logger

_enable_llm_tracer_ = None


def enable_llm_tracer() -> bool:
    ''' Check if viztracer is enabled. '''
    global _enable_llm_tracer_
    if _enable_llm_tracer_ is not None:
        return _enable_llm_tracer_
    _enable_llm_tracer_ = os.environ.get("TLLM_LLM_ENABLE_TRACER", "0") == "1"
    return _enable_llm_tracer_


try:
    from viztracer import VizTracer, get_tracer, log_sparse
except ImportError:
    if enable_llm_tracer():
        logger.warning(
            "VizTracer is not installed. Disabling tracer in LLM API.")
        _enable_llm_tracer_ = False

if enable_llm_tracer():
    logger.warning("LLM tracer is enabled. This may affect performance.")
else:
    # Dummy placeholders for VizTracer

    class VizTracer:

        def log_instant(self, *args, **kwargs):
            pass

        def register_exit(self, *args, **kwargs):
            pass

        def start(self, *args, **kwargs):
            pass

    def log_sparse(func: Optional[Callable] = None,
                   stack_depth: int = 0,
                   dynamic_tracer_check: bool = False) -> Callable:
        if func is None:
            return lambda f: log_sparse(f, stack_depth, dynamic_tracer_check)

        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)

        return wrapper

    _viz_tracer_dummy = VizTracer()

    def get_tracer():
        return _viz_tracer_dummy


_global_tracer_ = None


def global_tracer() -> VizTracer:
    ''' Get the global viztracer instance in the current process. '''
    if _global_tracer_ is None:
        return get_tracer()
    return _global_tracer_


def set_global_tracer(tracer: VizTracer):
    ''' Set the global viztracer instance in the current process. '''
    global _global_tracer_
    assert _global_tracer_ is None
    _global_tracer_ = tracer

from dataclasses import dataclass
from pathlib import Path
from typing import Iterable, Optional

from huggingface_hub import cached_assets_path
from tensorrt_llm import __version__ as TRTLLM_VERSION

from optimum.nvidia import LIBRARY_NAME
from optimum.nvidia.export import (
    PATH_FILE_CHECKPOINTS,
    PATH_FILE_ENGINES,
    PATH_FOLDER_CHECKPOINTS,
    PATH_FOLDER_ENGINES,
)


@dataclass
class Workspace:
    root: Path

    @staticmethod
    def from_hub_cache(
        model_id: str,
        device: str,
        namespace: str = LIBRARY_NAME,
        version: str = TRTLLM_VERSION,
        subpart: Optional[str] = None,
    ) -> "Workspace":
        assets_path = cached_assets_path(
            namespace, namespace=version, subfolder=model_id
        )
        assets_path = assets_path.joinpath(device)

        if subpart:
            assets_path = assets_path.joinpath(subpart)

        assets_path.mkdir(exist_ok=True, parents=True)
        return Workspace(assets_path)

    def __post_init__(self):
        if not self.checkpoints_path.exists():
            self.checkpoints_path.mkdir(parents=True)

        if not self.engines_path.exists():
            self.engines_path.mkdir(parents=True)

    @property
    def checkpoints_path(self) -> Path:
        """
        Folder path location holding all the engines
        :return: `Path`
        """
        return self.root / PATH_FOLDER_CHECKPOINTS

    @property
    def engines_path(self) -> Path:
        """
        Folder path location holding all the engines
        :return: `Path`
        """
        return self.root / PATH_FOLDER_ENGINES

    @property
    def checkpoints(self) -> Iterable[Path]:
        """
        Generator discovering all the checkpoint files present in this workspace
        :return:
        """
        return self.checkpoints_path.glob(PATH_FILE_CHECKPOINTS)

    def engines(self) -> Iterable[Path]:
        """
        Generator discovering all the engine files present in this workspace
        :return:
        """
        return self.engines_path.glob(PATH_FILE_ENGINES)

from tensorrt_llm.bindings.executor import FinishReason


class FinishedState:
    # State flags
    FINISHED_EOS = 1 << 0
    FINISHED_STOP_WORDS = 1 << 1
    FINISHED_MAX_LENGTH = 1 << 2
    FINISHED = FINISHED_EOS | FINISHED_STOP_WORDS | FINISHED_MAX_LENGTH
    SKIP_DECODING = 1 << 3

    def __init__(self, state=0):
        self._state = state

    @classmethod
    def empty(cls):
        return cls(0)

    @classmethod
    def finished(cls):
        return cls(cls.FINISHED)

    @classmethod
    def skip_decoding(cls):
        return cls(cls.SKIP_DECODING)

    @classmethod
    def finished_eos(cls):
        return cls(cls.FINISHED_EOS)

    @classmethod
    def finished_max_length(cls):
        return cls(cls.FINISHED_MAX_LENGTH)

    @classmethod
    def finished_stop_words(cls):
        return cls(cls.FINISHED_STOP_WORDS)

    def set_finished_eos(self):
        self._state |= self.FINISHED_EOS

    @property
    def is_finished_eos(self):
        return self._any_bit_set(self.FINISHED_EOS)

    def set_finished_stop_words(self):
        self._state |= self.FINISHED_STOP_WORDS

    @property
    def is_finished_stop_words(self):
        return self._any_bit_set(self.FINISHED_STOP_WORDS)

    def set_finished_max_length(self):
        self._state |= self.FINISHED_MAX_LENGTH

    @property
    def is_finished_max_length(self):
        return self._any_bit_set(self.FINISHED_MAX_LENGTH)

    def set_finished(self):
        self._state |= self.FINISHED

    @property
    def is_finished(self):
        return self._any_bit_set(self.FINISHED)

    def set_skip_decoding(self):
        self._state |= self.SKIP_DECODING

    @property
    def is_skip_decoding(self):
        return self._any_bit_set(self.SKIP_DECODING)

    def to_finish_reason(self):
        if self.is_finished_eos:
            return FinishReason.END_ID
        if self.is_finished_stop_words:
            return FinishReason.STOP_WORDS
        if self.is_finished_max_length:
            return FinishReason.LENGTH
        return FinishReason.NOT_FINISHED

    def to_underlying(self):
        return self._state

    def _any_bit_set(self, bits):
        return (self._state & bits) != 0

