from typing import List

import torch

from tensorrt_llm.runtime.kv_cache_manager import (GenerationSequence,
                                                   KVCacheManager)
from tensorrt_llm.runtime.memory_pools.pool import Pool


class PoolsKVCacheManager(object):

    def __init__(self, pools_metadata: List[Pool], max_blocks_per_seq,
                 num_blocks, tokens_per_block, head_size,
                 max_attention_window_size, beam_width, sink_token_len) -> None:
        self._num_pools = len(pools_metadata)
        self._kv_cache_managers = []

        for pool in pools_metadata:
            block_size = pool.num_kv_heads * tokens_per_block * head_size
            self._kv_cache_managers.append(
                KVCacheManager(
                    num_layers=pool.num_layers,
                    num_blocks=num_blocks,
                    block_size=block_size,
                    tokens_per_block=tokens_per_block,
                    max_blocks_per_seq=max_blocks_per_seq,
                    max_attention_window_size=max_attention_window_size,
                    sink_token_len=sink_token_len,
                    beam_width=beam_width,
                ))

    def add_sequence(self,
                     sequence: GenerationSequence,
                     context_len: int,
                     always_share_across_beam: bool = False):
        for kv_cache_manager in self._kv_cache_managers:
            kv_cache_manager.add_sequence(sequence, context_len,
                                          always_share_across_beam)

    def step(self, finished: List[bool]):
        for kv_cache_manager in self._kv_cache_managers:
            kv_cache_manager.step(finished)

    def get_block_offsets(self, beam_width: int) -> torch.Tensor:
        offsets = []
        for kv_cache_manager in self._kv_cache_managers:
            block_offset = kv_cache_manager.get_block_offsets(beam_width)
            offsets.append(block_offset)

        return torch.stack(offsets)

    def get_single_kv_cache_manager(self):
        assert len(self._kv_cache_managers
                   ) == 1, f"More then one kv cache manager exists"

        return self._kv_cache_managers[0]

    def has_single_pool(self):
        return len(self._kv_cache_managers) == 1

from typing import Union

from torch import nn

from tensorrt_llm._torch.model_config import ModelConfig
from tensorrt_llm._torch.models.checkpoints.hf.qwen2_moe_weight_mapper import \
    Qwen2MoeHfWeightMapper
from tensorrt_llm._torch.models.modeling_utils import register_mapper
from tensorrt_llm.models.modeling_utils import DecoderModelForCausalLM


@register_mapper("HF", "Qwen3MoeForCausalLM")
class Qwen3MoeHfWeightMapper(Qwen2MoeHfWeightMapper):

    def init_model_and_config(self, model: Union[nn.Module,
                                                 DecoderModelForCausalLM],
                              config: ModelConfig):
        super().init_model_and_config(model, config)
        self._num_kv_heads = model.config.num_key_value_heads if hasattr(
            model.config, 'num_key_value_heads'
        ) and model.config.num_key_value_heads is not None else model.config.num_attention_heads

    def should_skip_module(self, module_name: str) -> bool:
        if module_name.startswith("draft_model"):
            return True
        return super().should_skip_module(module_name)

    def _duplicate_kv_weights(self, module: nn.Module, new_name: str,
                              weights: dict):
        tensors_to_duplicate = ["weight", "bias"]
        if module.quant_config.quant_mode.has_nvfp4():
            tensors_to_duplicate.append("weight_scale")
        if module.quant_config.quant_mode.has_fp8_block_scales():
            tensors_to_duplicate.append("weight_scale_inv")

        if new_name in ['k_proj', 'v_proj']:
            num_kv_heads_list = [self._num_kv_heads
                                 ] * len(weights) if isinstance(
                                     self._num_kv_heads,
                                     int) else self._num_kv_heads
            processed_weights = {
                k:
                self._duplicate_kv(weight=v[:],
                                   num_kv_heads=num_kv_heads_list[i],
                                   tensor_parallel_size=self._tp_size)
                if k in tensors_to_duplicate else v
                for i, (k, v) in enumerate(weights.items())
            }
            return processed_weights

        return weights

from typing import List

import torch

from tensorrt_llm.runtime.kv_cache_manager import (GenerationSequence,
                                                   KVCacheManager)
from tensorrt_llm.runtime.memory_pools.pool import Pool


class PoolsKVCacheManager(object):

    def __init__(self, pools_metadata: List[Pool], max_blocks_per_seq,
                 num_blocks, tokens_per_block, head_size,
                 max_attention_window_size, beam_width, sink_token_len) -> None:
        self._num_pools = len(pools_metadata)
        self._kv_cache_managers = []

        for pool in pools_metadata:
            block_size = pool.num_kv_heads * tokens_per_block * head_size
            self._kv_cache_managers.append(
                KVCacheManager(
                    num_layers=pool.num_layers,
                    num_blocks=num_blocks,
                    block_size=block_size,
                    tokens_per_block=tokens_per_block,
                    max_blocks_per_seq=max_blocks_per_seq,
                    max_attention_window_size=max_attention_window_size,
                    sink_token_len=sink_token_len,
                    beam_width=beam_width,
                ))

    def add_sequence(self,
                     sequence: GenerationSequence,
                     context_len: int,
                     always_share_across_beam: bool = False):
        for kv_cache_manager in self._kv_cache_managers:
            kv_cache_manager.add_sequence(sequence, context_len,
                                          always_share_across_beam)

    def step(self, finished: List[bool]):
        for kv_cache_manager in self._kv_cache_managers:
            kv_cache_manager.step(finished)

    def get_block_offsets(self, beam_width: int) -> torch.Tensor:
        offsets = []
        for kv_cache_manager in self._kv_cache_managers:
            block_offset = kv_cache_manager.get_block_offsets(beam_width)
            offsets.append(block_offset)

        return torch.stack(offsets)

    def get_single_kv_cache_manager(self):
        assert len(self._kv_cache_managers
                   ) == 1, f"More then one kv cache manager exists"

        return self._kv_cache_managers[0]

    def has_single_pool(self):
        return len(self._kv_cache_managers) == 1

import json
from abc import ABC, abstractmethod
from typing import Optional

from tensorrt_llm.llmapi.disagg_utils import MetadataServerConfig
from tensorrt_llm.logger import logger

try:
    import etcd3
except Exception as e:
    logger.warning(f"etcd3 is not installed correctly: {e}")


class RemoteDictionary(ABC):

    @abstractmethod
    def get(self, key: str) -> str:
        pass

    @abstractmethod
    def put(self, key: str, value: str):
        pass

    @abstractmethod
    def remove(self, key: str):
        pass

    @abstractmethod
    def keys(self) -> list[str]:
        pass


class EtcdDictionary(RemoteDictionary):

    def __init__(self, host: str, port: int):
        self._client = etcd3.client(host, port)

    def get(self, key: str) -> str:
        return self._client.get(key)

    def put(self, key: str, value: str):
        self._client.put(key, value)

    def remove(self, key: str):
        self._client.delete(key)

    def keys(self) -> list[str]:
        # TODO: Confirm the final save key format
        # This implementation assumes that key is in the
        # format of "trtllm/executor_name/key"
        unique_keys = set()
        for _, metadata in self._client.get_all():
            key = metadata.key.decode('utf-8')
            sub_keys = key.split('/')
            if len(sub_keys) >= 2:
                top_prefix = "/".join(sub_keys[:2])
                unique_keys.add(top_prefix)
        return list(unique_keys)


class JsonDictionary:

    def __init__(self, dict: RemoteDictionary):
        self._dict = dict

    def get(self, key: str) -> str:
        bytes_data, _ = self._dict.get(key)
        return json.loads(bytes_data.decode('utf-8'))

    def put(self, key: str, value: str):
        self._dict.put(key, json.dumps(value))

    def remove(self, key: str):
        self._dict.remove(key)

    def keys(self) -> list[str]:
        return self._dict.keys()


def create_metadata_server(
    metadata_server_cfg: Optional[MetadataServerConfig]
) -> Optional[JsonDictionary]:

    if metadata_server_cfg is None:
        return None

    if metadata_server_cfg.server_type == 'etcd':
        dict = EtcdDictionary(host=metadata_server_cfg.hostname,
                              port=metadata_server_cfg.port)
    else:
        raise ValueError(
            f"Unsupported metadata server type: {metadata_server_cfg.server_type}"
        )

    return JsonDictionary(dict)

import asyncio
from typing import Mapping, Optional

from tensorrt_llm.executor.result import GenerationResult


class ScaffoldingResult:

    def __init__(self, streaming_event: Optional[asyncio.Event] = None):
        super().__init__()
        self.aqueue = asyncio.Queue()
        self.cur_output: GenerationResult = None
        self._done = False
        self.task_collections = None
        self.streaming_event = streaming_event

    def set_output(self, output: GenerationResult):
        self.aqueue.put_nowait(output)
        self._done = True

    async def set_output_async(self, output: GenerationResult):
        await self.aqueue.put(output)

    def set_task_collections(self, task_collections: Mapping[str,
                                                             "TaskCollection"]):
        self.task_collections = task_collections

    @property
    def outputs(self):
        return self.cur_output.outputs if self.cur_output else None

    @property
    def finished(self) -> bool:
        return self.cur_output is not None and self.cur_output.finished

    async def _aresult_step(self):
        # TODO: error handling or raise exception?
        response = await self.aqueue.get()
        if response is None:
            raise Exception("ScaffoldingLlm execution failed")
        self._handle_response(response)

    def result(self, timeout: Optional[float] = None) -> "ScaffoldingResult":
        if not self.finished:
            loop = asyncio.get_event_loop()
            asyncio.run_coroutine_threadsafe(self.aresult(), loop).result()
        return self

    async def aresult(self) -> "ScaffoldingResult":
        while not self.finished:
            await self._aresult_step()
        return self

    def __await__(self):
        return self.aresult().__await__()

    def __iter__(self):
        return self

    def __next__(self):
        if self._done and self.finished:
            raise StopIteration

        self._result_step()
        return self

    def __aiter__(self):
        return self

    async def __anext__(self):
        if self.finished:
            self.streaming_event.set() if self.streaming_event else None
        if self._done and self.finished:
            raise StopAsyncIteration

        await self._aresult_step()
        return self

    def _handle_response(self, response: GenerationResult):
        self.cur_output = response

# Adapted from
# https://github.com/vllm-project/vllm/blob/baaedfdb2d3f1d70b7dbcde08b083abfe6017a92/tests/utils.py
import subprocess
import sys
import time
from typing import List

import openai
import requests

from tensorrt_llm.llmapi.mpi_session import find_free_port


class RemoteOpenAIServer:
    DUMMY_API_KEY = "tensorrt_llm"
    MAX_SERVER_START_WAIT_S = 600  # wait for server to start for 60 seconds

    def __init__(
        self,
        model: str,
        cli_args: List[str],
    ) -> None:
        self.host = "localhost"
        self.port = find_free_port()

        cli_args += ["--host", f"{self.host}", "--port", f"{self.port}"]
        self.proc = subprocess.Popen(["trtllm-serve"] + [model] + cli_args,
                                     stdout=sys.stdout,
                                     stderr=sys.stderr)
        self._wait_for_server(url=self.url_for("health"),
                              timeout=self.MAX_SERVER_START_WAIT_S)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.proc.terminate()
        try:
            self.proc.wait(timeout=30)
        except subprocess.TimeoutExpired as e:
            self.proc.kill()
            self.proc.wait(timeout=30)

    def _wait_for_server(self, *, url: str, timeout: float):
        # run health check
        start = time.time()
        while True:
            try:
                if requests.get(url).status_code == 200:
                    break
            except Exception as err:
                result = self.proc.poll()
                if result is not None and result != 0:
                    raise RuntimeError("Server exited unexpectedly.") from err

                time.sleep(0.5)
                if time.time() - start > timeout:
                    raise RuntimeError(
                        "Server failed to start in time.") from err

    @property
    def url_root(self) -> str:
        return f"http://{self.host}:{self.port}"

    def url_for(self, *parts: str) -> str:
        return self.url_root + "/" + "/".join(parts)

    def get_client(self):
        return openai.OpenAI(
            base_url=self.url_for("v1"),
            api_key=self.DUMMY_API_KEY,
        )

    def get_async_client(self):
        return openai.AsyncOpenAI(
            base_url=self.url_for("v1"),
            api_key=self.DUMMY_API_KEY,
        )

from logging import getLogger
from pathlib import Path
from typing import Dict, Iterable, Union

import torch
from ammo.torch import export as ate
from ammo.torch import quantization as atq
from tensorrt_llm.quantization import QuantMode

from optimum.nvidia.configs import QuantizationConfig
from optimum.nvidia.lang import DataType


LOGGER = getLogger(__name__)


def get_ammo_config(mode: QuantMode, **quantizer_overrides):
    if mode.has_fp8_qdq():
        cfg = atq.FP8_DEFAULT_CFG
        if quantizer_overrides:
            for name, cfg in quantizer_overrides.items():
                cfg["quant_cfg"][name] = cfg
        return cfg
    else:
        raise NotImplementedError(
            "Only float8 quantization is supported for now. "
            "Please open up an issue on the optimum-nvidia Github with your need."
        )


def get_quantization_algorithm_name(qconfig: QuantizationConfig) -> str:
    mode = qconfig.mode

    if mode.has_fp8_qdq() or mode.has_fp8_kv_cache():
        return "fp8"
    elif mode.is_int4_weight_only():
        return "int4_awq"
    elif not mode.is_weight_only() and mode.is_int8():
        return "int8_sq"
    else:
        raise ValueError(f"Unable to determine quantization algorithm from: {qconfig}")


class AmmoQuantizer:
    def __init__(
        self,
        model: torch.nn.Module,
        qconfig: QuantizationConfig,
        dtype: DataType,
        tp_degree: int = -1,
        **quantizer_overrides,
    ):
        self._model = model
        self._qconfig = qconfig
        self._dtype = dtype
        self._tp_degree = tp_degree

        # Infer the target quantization elements
        self._ammo_config = get_ammo_config(qconfig.mode, **quantizer_overrides)

    def calibrate(self, calibration_data: Iterable[Dict[str, torch.Tensor]]):
        from tqdm import tqdm

        with torch.inference_mode():

            def _loop():
                for sample in tqdm(calibration_data):
                    inputs = {name: tensor[0].to("cuda") for name, tensor in sample.items()}
                    self._model(**inputs)

            atq.quantize(self._model, self._ammo_config, _loop)

    def save(self, path: Union[str, Path]):
        ate.export_model_config(
            self._model,  # The quantized model.
            "llama",  # The type of the model as str, e.g gptj, llama or gptnext.
            self._dtype.as_torch(),  # The exported weights data type as torch.dtype.
            get_quantization_algorithm_name(self._qconfig),  # The quantization algorithm applied, e.g. fp8 or int8_sq.
            path,  # The directory where the exported files will be stored.
            self._tp_degree,  # The number of GPUs used in the inference time for tensor parallelism.
        )

from abc import ABC

from tensorrt_llm.scaffolding.math_utils import (extract_answer,
                                                 get_majority_result)
from tensorrt_llm.scaffolding.task import GenerationTask


class ScaffoldingOutput:

    def __init__(self):
        self.output_str = None


class Controller(ABC):

    def generate(self, prompt: str, **kwargs) -> ScaffoldingOutput:
        raise NotImplementedError

    @staticmethod
    def create_task_from_prompt(prompt):
        generation_task = GenerationTask()
        generation_task.input_str = prompt
        generation_task.skip_tokenizer = False
        generation_task.skip_detokenizer = False
        return generation_task

    @staticmethod
    def create_output_from_generation_task(task: GenerationTask):
        scaffolding_output = ScaffoldingOutput()
        scaffolding_output.output_str = task.output_str
        return scaffolding_output


class SimpleController(Controller):
    # Simple Controller which is just a single autoregressive LLM call.

    def __init__(self):
        super().__init__()

    def generate(self, prompt: str, **kwargs) -> ScaffoldingOutput:
        task = self.create_task_from_prompt(prompt)
        # We only need a single generation task to handle simple case
        yield [task]
        # Should come here with task done and return field in task filled
        return self.create_output_from_generation_task(task)


class BestOfNController(Controller):

    def __init__(self, n: int = 5, custom_sampling_params: dict = None):
        super().__init__()
        self.n = n
        self.custom_sampling_params = custom_sampling_params

    def create_task_from_prompt(self, prompt):
        task = super().create_task_from_prompt(prompt)
        task.custom_sampling_params = self.custom_sampling_params
        return task

    def generate(self, prompt: str, **kwargs) -> ScaffoldingOutput:
        tasks = [self.create_task_from_prompt(prompt) for _ in range(self.n)]
        yield tasks
        return self.select_best_of_n(tasks)

    def select_best_of_n(self, tasks):

        def is_digit(result: str):
            extracted_answer = extract_answer(result)
            if extracted_answer is None:
                return False
            return extracted_answer.isdigit()

        results = [task.output_str for task in tasks]
        final_result, extracted_result = get_majority_result(
            results, result_extractor=extract_answer, result_validator=is_digit)
        if final_result is None:
            final_result = results[0]
        scaffolding_output = ScaffoldingOutput()
        scaffolding_output.output_str = final_result
        return scaffolding_output

from collections import Counter
from typing import List

import torch

import tensorrt_llm
from tensorrt_llm.runtime.memory_pools.pool import Pool


class MemoryPoolsAllocator(object):

    def __init__(self, num_blocks, tokens_per_block, head_size):
        self._pools_metadata = []
        self._pool_pointers = []
        self._pool_mapping = None

        self._num_blocks = num_blocks
        self._tokens_per_block = tokens_per_block
        self._head_size = head_size

    def allocate(self, dtype, num_kv_heads_per_layer: List[int], device="cuda"):
        self._num_kv_heads_per_layer = num_kv_heads_per_layer

        if isinstance(dtype, str):
            dtype = tensorrt_llm._utils.str_dtype_to_torch(dtype)
        kv_heads_unique_counter = Counter(self._num_kv_heads_per_layer)
        keys_to_indices = {}

        for idx, (kv_head,
                  num_layers) in enumerate(kv_heads_unique_counter.items()):
            keys_to_indices[kv_head] = idx
            cache_shape = (
                self._num_blocks,
                num_layers,
                2,
                kv_head,
                self._tokens_per_block,
                self._head_size,
            )
            self._pool_pointers.append(
                torch.empty(cache_shape, dtype=dtype, device=device))
            self._pools_metadata.append(
                Pool(num_kv_heads=kv_head, num_layers=num_layers))

        self._set_layers_mapping(keys_to_indices)

    def get_kv_cache_pool_pointers(self):
        return self._get_primarmy_secondary_pool_pointers()

    def _set_layers_mapping(self, keys_to_indices):
        layers_mapping = []
        for kv_size in self._num_kv_heads_per_layer:
            layers_mapping.append(keys_to_indices[kv_size])

        self._pool_mapping = torch.tensor(layers_mapping, dtype=torch.int32)

    def _get_primarmy_secondary_pool_pointers(self):
        assert len(self._pool_pointers
                   ) >= 1, "pool pointers haven't been initiated yet"
        data_ptr_pointers = torch.tensor(list(
            map(lambda x: x.data_ptr(), self._pool_pointers)),
                                         dtype=torch.int64)
        host_kv_cache_pool_pointers = torch.cat(
            (data_ptr_pointers.view(-1, 1),
             torch.zeros(len(self._pool_pointers), 1, dtype=torch.int64)),
            dim=1)

        return host_kv_cache_pool_pointers

    @classmethod
    def prepare_num_kv_heads_per_layer(cls, kv_head, num_layers):
        return [kv_head] * num_layers

    @property
    def pools_metadata(self):
        return self._pools_metadata

    @property
    def pool_mapping(self):
        return self._pool_mapping

