    def forward(self):
        self.m1.forward()
        self.register_network_output('o4', 4)


class Module4(Module):

    def __init__(self):
        super(Module4, self).__init__()
        self.layers = ModuleList([Module2(), Module2()])

    def forward(self):
        for l in self.layers:
            l.forward()


class TestModule(unittest.TestCase):

    def test_module(self):
        m = Module3()
        m.forward()

        self.assertEqual(4, len(list(m.named_modules())))
        self.assertEqual(5, len(list(m.named_network_outputs())))

    def test_module_list(self):
        m = Module4()
        m.forward()

        self.assertEqual(8, len(list(m.named_modules())))
        self.assertEqual(8, len(list(m.named_network_outputs())))

    def test_module_named_parameter(self):
        m = GroupNorm(2, 4)
        md = {k: v for k, v in m.named_parameters()}

        tm = torch.nn.GroupNorm(2, 4)
        tmd = {k: v for k, v in tm.named_parameters()}

        self.assertEqual(len(md), len(tmd))

        for k, _ in md.items():
            self.assertIn(k, tmd)

        for k, _ in tmd.items():
            self.assertIn(k, md)

from logging import getLogger
from typing import Dict, Iterable, Union
from pathlib import Path

import torch
from ammo.torch import quantization as atq, export as ate
from optimum.nvidia.configs import QuantizationConfig
from optimum.nvidia.lang import DataType
from tensorrt_llm.builder import BuilderConfig
from tensorrt_llm.quantization import QuantMode


LOGGER = getLogger(__name__)


def get_ammo_config(mode: QuantMode, **quantizer_overrides):
    if mode.has_fp8_qdq():
        cfg = atq.FP8_DEFAULT_CFG
        if quantizer_overrides:
            for name, cfg in quantizer_overrides.items():
                cfg['quant_cfg'][name] = cfg
        return cfg
    else:
        raise NotImplementedError(
            "Only float8 quantization is supported for now. "
            "Please open up an issue on the optimum-nvidia Github with your need."
        )


def get_quantization_algorithm_name(qconfig: QuantizationConfig) -> str:
    mode = qconfig.mode

    if mode.has_fp8_qdq() or mode.has_fp8_kv_cache():
        return "fp8"
    elif mode.is_int4_weight_only():
        return "int4_awq"
    elif not mode.is_weight_only() and mode.is_int8():
        return "int8_sq"
    else:
        raise ValueError(f"Unable to determine quantization algorithm from: {qconfig}")


class AmmoQuantizer:

    def __init__(
        self,
        model: torch.nn.Module,
        qconfig: QuantizationConfig,
        dtype: DataType,
        tp_degree: int = -1,
        **quantizer_overrides
    ):
        self._model = model
        self._qconfig = qconfig
        self._dtype = dtype
        self._tp_degree = tp_degree

        # Infer the target quantization elements
        self._ammo_config = get_ammo_config(qconfig.mode, **quantizer_overrides)

    def calibrate(self, calibration_data: Iterable[Dict[str, torch.Tensor]]):
        from tqdm import tqdm
        with torch.inference_mode():
            def _loop():
                for sample in tqdm(calibration_data):
                    inputs = {
                        name: tensor[0].to("cuda")
                        for name, tensor in sample.items()
                    }
                    self._model(**inputs)

            atq.quantize(self._model, self._ammo_config, _loop)

    def save(self, path: Union[str, Path]):
        ate.export_model_config(
            self._model,  # The quantized model.
            "llama",  # The type of the model as str, e.g gptj, llama or gptnext.
            self._dtype.as_torch(),  # The exported weights data type as torch.dtype.
            get_quantization_algorithm_name(self._qconfig),  # The quantization algorithm applied, e.g. fp8 or int8_sq.
            path, # The directory where the exported files will be stored.
            self._tp_degree,  # The number of GPUs used in the inference time for tensor parallelism.
        )

#!/usr/bin/env python3
import asyncio
import json
import os
from typing import Optional

import click

from tensorrt_llm.llmapi import LLM, KvCacheConfig, SamplingParams
from tensorrt_llm.llmapi._perf_evaluator import perform_faked_oai_postprocess
from tensorrt_llm.llmapi.utils import print_colored


@click.command()
@click.option("--model_dir", type=str, required=True)
@click.option("--tp_size", type=int, required=True)
@click.option("--engine_dir", type=str, default=None)
@click.option("--n", type=int, default=1)
@click.option("--best_of", type=int, default=None)
@click.option("--top_k", type=int, default=1)
def main(model_dir: str, tp_size: int, engine_dir: Optional[str], n: int,
         best_of: Optional[int], top_k: int):

    # Simplified postprocessing configuration
    postproc_config = {
        "_num_postprocess_workers": tp_size,
        "_postprocess_tokenizer_dir": model_dir,
        "_postprocess_result_handler": perform_faked_oai_postprocess
    }

    print_colored("Enabled OAI postprocessing\n", "yellow")

    llm = LLM(model_dir,
              tensor_parallel_size=tp_size,
              kv_cache_config=KvCacheConfig(free_gpu_memory_fraction=0.4),
              **postproc_config)

    if engine_dir is not None and os.path.abspath(
            engine_dir) != os.path.abspath(model_dir):
        llm.save(engine_dir)

    sampling_params = SamplingParams(max_tokens=10,
                                     end_id=-1,
                                     n=n,
                                     best_of=best_of,
                                     top_k=top_k)

    prompt = "A B C D E F"

    outputs = []

    async def generate_async():
        async for output in llm.generate_async(prompt,
                                               sampling_params=sampling_params,
                                               streaming=True):
            print(output)
            outputs.append(output.outputs[0]._postprocess_result)

    asyncio.run(generate_async())

    expected = "G H I J K L M N O P"
    actual = get_concatenated_content(outputs)
    assert actual == expected, f"Expected '{expected}', got '{actual}'"


def get_concatenated_content(outputs):
    content = []
    for chunk in outputs:
        for line in chunk:
            line = line.strip()
            if not line.startswith('data: '):
                continue

            json_str = line.split('data: ', 1)[1]
            if json_str == '[DONE]':
                continue

            data = json.loads(json_str)
            for choice in data.get('choices', []):
                if 'delta' in choice and 'content' in choice['delta']:
                    content_value = choice['delta']['content']
                    if content_value is not None:
                        content.append(content_value)
    return ''.join(content)


if __name__ == '__main__':
    main()

