from abc import ABC, abstractmethod
from typing import Any

from torch import nn

from tensorrt_llm._torch.model_config import ModelConfig
from tensorrt_llm._torch.models.checkpoints.auto_mapper import \
    AutoCheckpointMapper
from tensorrt_llm._torch.models.checkpoints.base_config_loader import \
    BaseConfigLoader
from tensorrt_llm._torch.models.checkpoints.base_weight_loader import \
    BaseWeightLoader
from tensorrt_llm._torch.models.checkpoints.base_weight_mapper import \
    BaseWeightMapper
from tensorrt_llm._torch.models.modeling_utils import \
    CHECKPOINT_LOADER_FORMAT_DEFAULT_MAPPING


class BaseCheckpointLoader(ABC):

    @abstractmethod
    def get_default_weight_loader(self) -> BaseWeightLoader:
        raise NotImplementedError

    @abstractmethod
    def get_default_config_loader(self) -> BaseConfigLoader:
        raise NotImplementedError

    @abstractmethod
    def cleanup(self) -> None:
        raise NotImplementedError

    @property
    @abstractmethod
    def weight_loader(self) -> BaseWeightLoader:
        ...

    @property
    @abstractmethod
    def weight_mapper(self) -> BaseWeightMapper:
        ...

    @property
    @abstractmethod
    def config_loader(self) -> BaseConfigLoader:
        ...

    @property
    @abstractmethod
    def checkpoint_format(self) -> str:
        ...

    def load_config(self, checkpoint_dir: str, **kwargs) -> ModelConfig:
        return self.config_loader.load(checkpoint_dir, **kwargs)

    def load_weights(self, checkpoint_dir: str, **kwargs) -> dict[str, Any]:
        return self.weight_loader.load_weights(checkpoint_dir, **kwargs)

    @classmethod
    def get(cls, checkpoint_format: str, **kwargs) -> "BaseCheckpointLoader":
        try:
            return CHECKPOINT_LOADER_FORMAT_DEFAULT_MAPPING[checkpoint_format](
                **kwargs)
        except KeyError:
            raise ValueError(
                f"Checkpoint loader for format {checkpoint_format} not found, "
                f"available formats are: {CHECKPOINT_LOADER_FORMAT_DEFAULT_MAPPING.keys()}"
            )

    def get_initialized_weight_mapper(self, model: nn.Module,
                                      config: ModelConfig) -> BaseWeightMapper:
        weight_mapper = None
        if self.weight_mapper is not None:
            self.weight_mapper.init_model_and_config(model, config)
            return self.weight_mapper
        else:
            # The name of the registered mapper should be the model architecture
            if config.pretrained_config and config.pretrained_config.architectures:
                model_arch = config.pretrained_config.architectures[0]
            else:
                raise ValueError(
                    "Cannot determine model architecture from config")
            weight_mapper = AutoCheckpointMapper.get(self.checkpoint_format,
                                                     model_arch)
            weight_mapper.init_model_and_config(model, config)
            self.weight_mapper = weight_mapper
            return weight_mapper

# Adapted from
# https://github.com/vllm-project/vllm/blob/baaedfdb2d3f1d70b7dbcde08b083abfe6017a92/tests/utils.py
import os
import subprocess
import sys
import time
from typing import List

import openai
import requests

from tensorrt_llm.llmapi.mpi_session import find_free_port


class RemoteOpenAIServer:
    DUMMY_API_KEY = "tensorrt_llm"
    MAX_SERVER_START_WAIT_S = 600  # wait for server to start for 600 seconds

    def __init__(self,
                 model: str,
                 cli_args: List[str] = None,
                 llmapi_launch: bool = False,
                 port: int = None) -> None:
        self.host = "localhost"
        self.port = port if port is not None else find_free_port()
        self.rank = os.environ.get("SLURM_PROCID", 0)

        args = ["--host", f"{self.host}", "--port", f"{self.port}"]
        if cli_args:
            args += cli_args
        launch_cmd = ["trtllm-serve"] + [model] + args
        if llmapi_launch:
            # start server with llmapi-launch on multi nodes
            launch_cmd = ["trtllm-llmapi-launch"] + launch_cmd
        self.proc = subprocess.Popen(launch_cmd,
                                     stdout=sys.stdout,
                                     stderr=sys.stderr)
        self._wait_for_server(url=self.url_for("health"),
                              timeout=self.MAX_SERVER_START_WAIT_S)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.proc.terminate()
        try:
            self.proc.wait(timeout=30)
        except subprocess.TimeoutExpired as e:
            self.proc.kill()
            self.proc.wait(timeout=30)

    def _wait_for_server(self, *, url: str, timeout: float):
        # run health check on the first rank only.
        start = time.time()
        while True:
            try:
                if self.rank == 0:
                    if requests.get(url).status_code == 200:
                        break
                else:
                    time.sleep(timeout)
                    break
            except Exception as err:
                result = self.proc.poll()
                if result is not None and result != 0:
                    raise RuntimeError("Server exited unexpectedly.") from err

                time.sleep(0.5)
                if time.time() - start > timeout:
                    raise RuntimeError(
                        "Server failed to start in time.") from err

    @property
    def url_root(self) -> str:
        return f"http://{self.host}:{self.port}"

    def url_for(self, *parts: str) -> str:
        return self.url_root + "/" + "/".join(parts)

    def get_client(self):
        return openai.OpenAI(
            base_url=self.url_for("v1"),
            api_key=self.DUMMY_API_KEY,
        )

    def get_async_client(self, **kwargs):
        return openai.AsyncOpenAI(base_url=self.url_for("v1"),
                                  api_key=self.DUMMY_API_KEY,
                                  **kwargs)

# copied from: https://github.com/NVIDIA/TensorRT-LLM/blob/v0.18.1/examples/enc_dec/helper.py

import typing
from typing import Union

import numpy as np
import torch  # pytype: disable=import-error

from tensorrt_llm._utils import str_dtype_to_torch


def split(v: Union[np.ndarray, torch.Tensor], tp_size: int, tp_rank: int, dim=0):
    if tp_size == 1:
        if isinstance(v, np.ndarray):
            return np.ascontiguousarray(v.copy())
        else:
            return v.clone().detach()
    assert len(v.shape) > 1 or dim == 0
    if isinstance(v, np.ndarray):
        return np.ascontiguousarray(np.split(v, tp_size, axis=dim)[tp_rank].copy())
    else:
        assert v.shape[dim] % tp_size == 0, (
            "Unable to split: shape={v.shape} (dim={dim}) tp_size={tp_size}."
        )
        split_size = v.shape[dim] // tp_size
        return v.split(split_size, dim=dim)[tp_rank].clone().detach()


def reshape(v: torch.Tensor, shape=None):
    if shape is None:
        return v.contiguous()
    else:
        return v.reshape(shape).contiguous()


def fuse_qkv_one_layer(
    params,
    attn_module_name,
    trtllm_layer_name,
    tp_size,
    tp_rank,
    model_type,
    weight_shape,
    bias_shape,
):
    qkv_module_names = get_qkv_module_name(model_type)

    weight = {}

    # fuse weights of q, k, v
    q_w = params[f"{attn_module_name}.{qkv_module_names['q']}.weight"]
    k_w = params[f"{attn_module_name}.{qkv_module_names['k']}.weight"]
    v_w = params[f"{attn_module_name}.{qkv_module_names['v']}.weight"]

    # fuse qkv weight
    shape = q_w.shape  # (do, din)
    qkv_w = torch.cat([q_w, k_w, v_w], dim=0).reshape(
        [3, shape[0], shape[1]]
    )  # (3, do, din)
    qkv_w = split(qkv_w, tp_size, tp_rank, dim=1)
    weight[f"{trtllm_layer_name}.qkv.weight"] = reshape(qkv_w, shape=weight_shape)

    # fuse qkv biases if present
    if (
        f"{attn_module_name}.{qkv_module_names['q']}.bias" in params.keys()
        and params[f"{attn_module_name}.{qkv_module_names['q']}.bias"] is not None
    ):
        q_b = params[f"{attn_module_name}.{qkv_module_names['q']}.bias"]
        k_b = params[f"{attn_module_name}.{qkv_module_names['k']}.bias"]
        v_b = params[f"{attn_module_name}.{qkv_module_names['v']}.bias"]
        shape = q_b.shape[0]  # (do,)
        qkv_b = torch.cat([q_b, k_b, v_b], dim=0).reshape([3, shape])  # (3, do)
        qkv_b = split(qkv_b, tp_size, tp_rank, dim=1)
        weight[f"{trtllm_layer_name}.qkv.bias"] = reshape(qkv_b, shape=bias_shape)
    return weight


def get_qkv_module_name(model_type):
    if model_type in ["t5", "blip2"]:
        q = "q"
        k = "k"
        v = "v"
    elif model_type == "bart" or model_type == "nmt":
        q = "q_proj"
        k = "k_proj"
        v = "v_proj"
    elif model_type == "pix2struct":
        q = "query"
        k = "key"
        v = "value"
    return {"q": q, "k": k, "v": v}


def convert_weight_to_dtype(
    params: typing.Dict[str, torch.Tensor], dtype: typing.Optional[np.dtype] = None
):
    if dtype is not None:
        assert isinstance(dtype, str), f"dtype must be str, but get type {type(dtype)}"
        for name in params.keys():
            params[name] = params[name].to(str_dtype_to_torch(dtype))

import typing
from typing import Union

import numpy as np
