import copy
from enum import Enum
from typing import List

from tensorrt_llm.scaffolding import (Controller, ParallelProcess,
                                      ScaffoldingLlm, Task, TaskCollection,
                                      TaskStatus, Worker, with_task_collection)


class DummyTask(Task):

    def __init__(self):
        self.before_flag = False
        self.after_flag = False

    @staticmethod
    def create_from_prompt(prompt: str) -> "DummyTask":
        task = DummyTask()
        return task

    def create_scaffolding_output(self):
        return None

    def verify(self):
        assert self.before_flag, "task.before_flag has not been set to True"
        assert self.after_flag, "task.after_flag has not been set to True"


class DummyTaskCollection(TaskCollection):

    def __init__(self):
        super().__init__()
        self.task_count = 0

    def before_yield(self, tasks: List[Task]):
        for task in tasks:
            task.before_flag = True

    def after_yield(self, tasks: List[Task]):
        for task in tasks:
            task.after_flag = True
            self.task_count += 1


class DummyControllerBase(Controller):

    class WorkerTag(Enum):
        DUMMY = "dummy"

    def __init__(self, expected_task_count: int):
        super().__init__()
        self.expected_task_count = expected_task_count

    def generate(self, prompt: str, **kwargs):
        task = DummyTask.create_from_prompt(prompt)
        yield from self.process([task], **kwargs)
        return task.create_scaffolding_output()

    def verify(self):
        assert self.task_collections[
            "dummy"].task_count == self.expected_task_count, (
                "task count is not as expected")


@with_task_collection("dummy", DummyTaskCollection)
# verify that we can have multiple task collections and they works separately
@with_task_collection("dummy2", DummyTaskCollection)
class DummyController(DummyControllerBase):

    def process(self, tasks: List[Task], **kwargs):
        for task in tasks:
            task.worker_tag = self.WorkerTag.DUMMY

        yield tasks

        for task in tasks:
            task.verify()

        self.verify()


@with_task_collection("dummy", DummyTaskCollection)
class DummyParallelController(DummyControllerBase):

    def __init__(self, controllers):
        expected_task_count = sum(
            [controller.expected_task_count for controller in controllers])
        super().__init__(expected_task_count)
        self.controllers = controllers

    def process(self, tasks: List[Task], **kwargs):
        tasks_list = [
            copy.deepcopy(tasks) for _ in range(len(self.controllers))
        ]

        kwargs_list = [kwargs for _ in range(len(self.controllers))]

        yield ParallelProcess(self.controllers, tasks_list, kwargs_list)

        for tasks in tasks_list:
            for task in tasks:
                task.verify()

        tasks = tasks_list[0]
        self.verify()


class DummyWorker(Worker):

    async def dummy_handler(self, task: DummyTask):
        return TaskStatus.SUCCESS

    task_handlers = {DummyTask: dummy_handler}


def run(controller, expected_task_count):
    worker = DummyWorker()
    llm = ScaffoldingLlm(controller, {DummyController.WorkerTag.DUMMY: worker})

    llm.generate("")
    llm.shutdown()


def test_dummy_task_collection():
    controller = DummyController(1)
    run(controller, 1)

    controller = DummyParallelController(
        [DummyController(1), DummyController(1)])
    run(controller, 2)

import sys

from tensorrt_llm.bindings.exceptions import RequestSpecificException


def test_basic_exception_creation():
    """Test basic exception creation and catching."""
    try:
        raise RequestSpecificException("Test error message")
    except RequestSpecificException as e:
        assert isinstance(e, RequestSpecificException)
        assert "Test error message" in str(e)


def test_exception_inheritance():
    """Test that exception properly inherits from base Exception."""
    try:
        raise RequestSpecificException("Test inheritance")
    except Exception as e:  # Should catch base Exception
        assert isinstance(e, RequestSpecificException)
    except RequestSpecificException as e:  # Should also catch specific type
        assert isinstance(e, RequestSpecificException)


def test_exception_attributes_exist():
    """Test that exception has the expected attributes."""
    try:
        raise RequestSpecificException("Test attributes")
    except RequestSpecificException as e:
        # Check that attributes exist (they might be None if not set by C++)
        assert hasattr(e, 'request_id'), "request_id attribute missing"
        assert hasattr(e, 'error_code'), "error_code attribute missing"


def test_exception_traceback():
    """Test that exception provides proper traceback information."""
    try:
        raise RequestSpecificException("Test traceback")
    except RequestSpecificException as e:
        # Check that we can get traceback info
        exc_type, exc_value, exc_traceback = sys.exc_info()
        assert exc_type == RequestSpecificException
        assert exc_value == e
        assert exc_traceback is not None


def test_exception_equality():
    """Test exception equality and identity."""
    try:
        raise RequestSpecificException("Test equality")
    except RequestSpecificException as e1:
        try:
            raise RequestSpecificException("Test equality")
        except RequestSpecificException as e2:
            # Exceptions should not be equal even with same message
            assert e1 != e2, "Different exceptions should not be equal"
            assert e1 is not e2, "Different exceptions should not be identical"


def test_exception_context():
    """Test exception context and chaining."""
    try:
        try:
            raise RequestSpecificException("Inner exception")
        except RequestSpecificException as inner:
            raise RequestSpecificException("Outer exception") from inner
    except RequestSpecificException as outer:
        assert outer.__cause__ is not None
        assert isinstance(outer.__cause__, RequestSpecificException)


def test_cpp_exception_translation():
    """Test that C++ exceptions are properly translated to Python."""
    try:
        # This would normally be triggered by C++ code
        # For now, we'll test the Python exception creation
        raise RequestSpecificException("Test C++ translation")
    except RequestSpecificException as e:
        # Check that the exception was properly created
        assert isinstance(e, RequestSpecificException)


def test_exception_multiple_instances():
    """Test creating multiple exception instances."""
    exceptions = []
    for i in range(5):
        try:
            raise RequestSpecificException(f"Exception {i}")
        except RequestSpecificException as e:
            exceptions.append(e)

    assert len(exceptions) == 5
    for i, e in enumerate(exceptions):
        assert isinstance(e, RequestSpecificException)
        assert f"Exception {i}" in str(e)

