    getSMVersion() < 80,
    reason="This test is not supported in pre-Ampere architecture")
skip_pre_ada = pytest.mark.skipif(
    getSMVersion() < 89,
    reason="This test is not supported in pre-Ada architecture")
skip_pre_hopper = pytest.mark.skipif(
    getSMVersion() < 90,
    reason="This test is not supported in pre-Hopper architecture")

force_ampere = pytest.mark.skipif(
    getSMVersion() < 80 or getSMVersion() > 89,
    reason="This test is only enabled in Ampere architecture")


def is_bf16(dtype):
    return dtype == 'bfloat16' or dtype == 'bf16' or dtype == torch.bfloat16


def skip_fp32_accum_pre_ampere(context_fmha_type):
    if context_fmha_type == ContextFMHAType.enabled_with_fp32_acc and getSMVersion(
    ) < 80:
        pytest.skip(
            "ContextFMHAType with fp32 acc is not supported in pre-Ampere architecture"
        )


def skip_bf16_pre_ampere(dtype):
    if is_bf16(dtype) and getSMVersion() < 80:
        pytest.skip("bfloat16 is not supported in pre-Ampere architecture")


def skip_fp8_pre_ada(use_fp8):
    if use_fp8 and getSMVersion() < 89:
        pytest.skip("FP8 is not supported on pre-Ada architectures")


def skip_bf16_fp32_accum(dtype, context_fmha_type):
    if is_bf16(dtype
               ) and context_fmha_type == ContextFMHAType.enabled_with_fp32_acc:
        pytest.skip(
            "bfloat16 Context FMHA will always accumulate on FP32, so it has been tested with ContextFMHAType.enabled"
        )


def ammo_installed():
    try:
        # isort: off
        import ammo.torch.quantization as atq  # NOQA
        from ammo.torch.export import export_model_config  # NOQA
        # isort: on
        return True
    except Exception:
        return False


skip_no_ammo = pytest.mark.skipif(not ammo_installed(),
                                  reason="AMMO is not installed")


# This function names will make all unit tests names to show the values of all parameters in @parameterized.expand
def unittest_name_func(testcase_func, param_num, param):
    expand_params = lambda params: '_'.join([
        expand_params(x) if isinstance(x, (list, tuple)) else str(x)
        for x in params
    ])
    name = expand_params(param.args)
    return "%s_%s" % (
        testcase_func.__name__,
        parameterized.to_safe_name(name),
    )

import torch.distributed as dist
from mpi4py import MPI
import os
import torch
import random
from tensorrt_llm._utils import mpi_broadcast

from cosmos_rl.utils.constant import COSMOS_HTTP_RETRY_CONFIG
from cosmos_rl.utils.logging import logger
from cosmos_rl.utils.network_util import find_available_port

OMPI_COMM_TYPE_HOST = 9

global_comm = MPI.COMM_WORLD


def set_mpi_comm(new_comm):
    """
    Set the MPI communicator to be used by the distributed package.
    """
    global global_comm
    global_comm = new_comm


def mpi_comm():
    return global_comm


local_comm = mpi_comm().Split_type(split_type=OMPI_COMM_TYPE_HOST)


local_comm = mpi_comm().Split_type(split_type=OMPI_COMM_TYPE_HOST)


def mpi_rank():
    return mpi_comm().Get_rank()


def global_mpi_rank():
    return MPI.COMM_WORLD.Get_rank()


def global_mpi_size():
    return MPI.COMM_WORLD.Get_size()


def mpi_world_size():
    return mpi_comm().Get_size()


def local_mpi_rank():
    return local_comm.Get_rank()


def local_mpi_size():
    return local_comm.Get_size()


def init_distributed_with_MPI():
    # FIXME: (lms) Support multi-nodes.
    local_rank = mpi_rank()
    global_rank = global_mpi_rank()
    world_size = global_mpi_size()

    if world_size == 1:
        return

    if dist.is_initialized():
        return

    cosmos_world_size = os.environ.get("COSMOS_WORLD_SIZE", None)
    cosmos_local_world_size = os.environ.get("COSMOS_LOCAL_WORLD_SIZE", None)

    assert cosmos_world_size is not None, "COSMOS_WORLD_SIZE is not set."
    assert cosmos_local_world_size is not None, "COSMOS_LOCAL_WORLD_SIZE is not set."

    if cosmos_world_size is not None:
        assert world_size == int(
            cosmos_world_size
        ), "COSMOS_WORLD_SIZE is not consistent with the world size of MPI."
    if cosmos_local_world_size is not None:
        assert mpi_world_size() == int(
            cosmos_local_world_size
        ), "COSMOS_LOCAL_WORLD_SIZE is not consistent with the local world size of MPI."

    rdzv_endpoint = os.environ.get("COSMOS_RDZV_ENDPOINT", None)
    assert rdzv_endpoint is not None, "COSMOS_RDZV_ENDPOINT is not set."
    rdzv_host, rdzv_port = rdzv_endpoint.split(":")

    torch.cuda.set_device(local_rank)
    max_port = 65535
    min_port = 12371

    for _ in range(COSMOS_HTTP_RETRY_CONFIG.max_retries):
        if not int(rdzv_port):
            rdzv_port = None
            if mpi_rank() == 0:
                rdzv_port = find_available_port(
                    start_port=random.randint(min_port, max_port)
                )
            rdzv_port = mpi_broadcast(rdzv_port, root=0)

        os.environ["LOCAL_RANK"] = str(local_rank)
        os.environ["RANK"] = str(global_rank)
        os.environ["WORLD_SIZE"] = str(world_size)
        os.environ["MASTER_ADDR"] = rdzv_host
        os.environ["MASTER_PORT"] = str(rdzv_port)

        init_method = f"tcp://{os.environ['MASTER_ADDR']}:{os.environ['MASTER_PORT']}"

        try:
            # We use nccl and gloo backend
            dist.init_process_group(
                "cuda:nccl,cpu:gloo",
                world_size=world_size,
                rank=local_rank,
                init_method=init_method,
            )
        except dist.DistNetworkError:
            continue
        if dist.is_initialized():
            break
    else:
        raise RuntimeError(
            f"Failed to initialize distributed environment after {COSMOS_HTTP_RETRY_CONFIG.max_retries} retries."
        )

    logger.info(
        f"[Rollout] init torch distributed environment inside trtllm worker with tcp://{rdzv_host}:{rdzv_port} in rank {local_rank}."
    )

