"""The LLAMA/LLAMA2 decoder implementation."""

from typing import Optional

from tensorrt_llm.functional import non_gated_version
from tensorrt_llm.layers import AttentionMaskType, PositionEmbeddingType
from tensorrt_llm.models.llama.model import LLaMADecoderLayer
from typing_extensions import override

from ..model_config import LINEAR_COLUMN, LINEAR_ROW, AttentionConfig, LayernormConfig, LinearConfig, MLPConfig
from .decoder import DecoderLayerBuilder, DecoderLayerConfigBuilder


class LLAMADecoderLayerConfigBuilder(DecoderLayerConfigBuilder):
    """The LLAMA implementation of the DecoderLayerConfigBuilder."""

    @override
    def hidden_act_fn(self, layer):
        return layer.mlp.act_fn

    @override
    def infer_num_attention_heads(self, layer):
        return layer.self_attn.num_heads

    @override
    def infer_num_kv_heads(self, layer):
        return layer.self_attn.num_key_value_heads

    @override
    def infer_max_position_embeddings(self, layer):
        return layer.self_attn.max_position_embeddings

    @override
    def build_input_layernorm(self, layer) -> LayernormConfig:
        return LayernormConfig.from_nn_module(layer.input_layernorm, dtype=self.dtype)

    @override
    def build_attention(self, layer) -> AttentionConfig:
        config = AttentionConfig()
        config.qkv = LinearConfig.from_qkv_nn_modules(
            [layer.self_attn.q_proj, layer.self_attn.k_proj, layer.self_attn.v_proj],
            rank=self.rank,
            tensor_parallel=self.tensor_parallel,
            dtype=self.dtype,
        )

        config.dense = LinearConfig.from_nn_module(
            layer.self_attn.o_proj, LINEAR_ROW, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )

        return config

    @override
    def build_mlp(self, layer) -> MLPConfig:
        config = MLPConfig()
        config.fc = LinearConfig.from_nn_module(
            layer.mlp.gate_proj, LINEAR_COLUMN, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )
        config.proj = LinearConfig.from_nn_module(
            layer.mlp.down_proj, LINEAR_ROW, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )
        config.gate = LinearConfig.from_nn_module(
            layer.mlp.up_proj, LINEAR_COLUMN, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )

        return config

    @override
    def build_post_layernorm(self, layer) -> Optional[LayernormConfig]:
        return LayernormConfig.from_nn_module(layer.post_attention_layernorm, dtype=self.dtype)


class LLAMADecoderLayerBuilder(DecoderLayerBuilder):
    """The LLAMA implementation of the DecoderLayer."""

    @override
    def build_decoder(self, layer):
        return LLaMADecoderLayer(
            layer_id=self.layer_id,
            hidden_size=self.hidden_size,
            num_attention_heads=self.num_attention_heads,
            num_kv_heads=self.num_kv_heads,
            max_position_embeddings=self.max_position_embeddings,
            dtype=self.dtype,
            attention_mask_type=AttentionMaskType.causal,
            hidden_act=non_gated_version(self.hidden_act),
            position_embedding_type=PositionEmbeddingType.rope_gpt_neox,
            mlp_hidden_size=layer.ffn_hidden_size_local * self.tensor_parallel,
            tp_group=self.tp_group,
            tp_size=self.tensor_parallel,
        )

#!/usr/bin/env python
import subprocess
import sys

from llm_examples import *

from tensorrt_llm.hlapi.utils import print_colored


@click.group()
def cli():
    pass


@click.command('run_single_gpu')
@click.option('--prompt', type=str, default="What is LLM?")
@click.option('--model_dir', type=str, help='The directory of the model.')
@click.option('--examples_root',
              type=str,
              help='The root directory of the examples.')
@click.option('--llm_examples',
              type=str,
              help='The path to the llm_examples.py.',
              default='llm_examples.py')
@click.option('--engine_dir',
              type=str,
              help='The directory of the engine.',
              default="/tmp/hlapi.engine.example")
def run_single_gpu(
    prompt: str,
    model_dir: str,
    examples_root: str,
    llm_examples: str,
    engine_dir: str,
):
    run_example(
        "Running LLM from HuggingFace model",
        f"{sys.executable} {llm_examples} run_llm_generate --prompt=\"{prompt}\" --model_dir={model_dir} --engine_dir={engine_dir}"
    )

    run_example(
        "Running LLM from built engine with streaming enabled",
        f"{sys.executable} {llm_examples} run_llm_generate_async_example --prompt=\"{prompt}\" --model_dir={engine_dir} --streaming"
    )

    run_example(
        "Running LLM with async future",
        f"{sys.executable} {llm_examples} run_llm_with_async_future --prompt=\"{prompt}\" --model_dir={engine_dir}"
    )


@click.command("run_multi_gpu")
@click.option('--prompt', type=str, default="What is LLM?")
@click.option('--model_dir', type=str, help='The directory of the model.')
@click.option('--examples_root',
              type=str,
              help='The root directory of the examples.')
@click.option('--llm_examples',
              type=str,
              help='The path to the llm_examples.py.',
              default='llm_examples.py')
@click.option('--engine_dir',
              type=str,
              help='The directory of the engine.',
              default="/tmp/hlapi.engine.example")
@click.option('--run_autopp',
              type=bool,
              help='Whether to run with auto parallel.',
              default=True)
def run_multi_gpu(
    prompt: str,
    model_dir: str,
    examples_root: str,
    llm_examples: str,
    engine_dir: str,
    run_autopp: bool = True,
):
    run_example(
        "Running LLM from HuggingFace model with TP enabled",
        f"{sys.executable} {llm_examples} run_llm_generate --prompt=\"{prompt}\" --model_dir={model_dir} --tp_size=2 --engine_dir={engine_dir}.tp2"
    )

    run_example(
        "Running LLM from built engine with streaming enabled and TP=2",
        f"{sys.executable} {llm_examples} run_llm_generate_async_example --prompt=\"{prompt}\" --model_dir={engine_dir}.tp2 --streaming"
    )  # Loading the engine with TP=2.

    if run_autopp:
        run_example(
            "Running LLM with auto parallel",
            f"{sys.executable} {llm_examples} run_llm_with_auto_parallel --prompt=\"{prompt}\" --model_dir={model_dir} --world_size=2"
        )


@click.command("run_quant")
@click.option('--prompt', type=str, default="What is LLM?")
@click.option('--model_dir', type=str, help='The directory of the model.')
@click.option('--examples_root',
              type=str,
              help='The root directory of the examples.')
@click.option('--llm_examples',
              type=str,
              help='The path to the llm_examples.py.',
              default='llm_examples.py')
def run_quant(
    prompt: str,
    model_dir: str,
    examples_root: str,
    llm_examples: str,
):
    run_example(
        "Running LLM with quantization",
        f"{sys.executable} {llm_examples} run_llm_with_quantization --quant_type=int4_awq --prompt=\"{prompt}\" --model_dir={model_dir}"
    )


def run_example(hint: str, command: str):
    print_colored(hint + "\n", "bold_green")
    print(command)
    subprocess.run(command, shell=True, check=True)


if __name__ == '__main__':
    cli.add_command(run_single_gpu)
    cli.add_command(run_multi_gpu)
    cli.add_command(run_quant)
    cli()

