import os
from dataclasses import dataclass
from typing import List, Optional, Union

import numpy as np
import torch

from tensorrt_llm.inputs.multimodal import MultimodalParams

from ..disaggregated_params import DisaggregatedParams
from ..llmapi.llm_utils import KvCacheRetentionConfig
from ..sampling_params import SamplingParams
from ..scheduling_params import SchedulingParams
from .postproc_worker import PostprocParams

__all__ = [
    "LoRARequest",
    "PromptAdapterRequest",
    "GenerationRequest",
]


@dataclass(slots=True)
class LoRARequest:
    """ Request for a LoRA adapter. """
    lora_name: str
    lora_int_id: int
    lora_path: str = ""
    lora_ckpt_source: str = "hf"

    def __post_init__(self):
        if self.lora_path is not None and not os.path.exists(self.lora_path):
            raise ValueError(f"lora_path ({self.lora_path}) does not exist.")
        if self.lora_ckpt_source not in ["hf", "nemo"]:
            raise ValueError(
                f"lora_ckpt_source must be 'hf' or 'nemo', got '{self.lora_ckpt_source}'"
            )

    @property
    def adapter_id(self):
        return self.lora_int_id

    @property
    def name(self):
        return self.lora_name

    @property
    def path(self):
        return self.lora_path

    @property
    def ckpt_source(self):
        return self.lora_ckpt_source


@dataclass(slots=True)
class PromptAdapterRequest:
    """
    Request for a Prompt adapter.
    """
    prompt_adapter_name: str
    prompt_adapter_id: int
    prompt_adapter_local_path: str = ""

    def __post_init__(self):
        if not os.path.exists(self.prompt_adapter_local_path):
            raise RuntimeError(
                f"prompt_adapter_local_path ({self.prompt_adapter_local_path}) does not exist."
            )

    @property
    def adapter_id(self):
        return self.prompt_adapter_id

    @property
    def name(self):
        return self.prompt_adapter_name

    @property
    def local_path(self):
        return self.prompt_adapter_local_path


class GenerationRequest:

    def __init__(
        self,
        prompt_token_ids: Union[torch.Tensor, np.ndarray,
                                Union[List[int], List[List[int]]]],
        sampling_params: SamplingParams,
        query_token_ids: Optional[Union[torch.Tensor, np.ndarray, list]] = None,
        lora_request: Optional[LoRARequest] = None,
        prompt_adapter_request: Optional[PromptAdapterRequest] = None,
        streaming: bool = False,
        kv_cache_retention_config: Optional[KvCacheRetentionConfig] = None,
        disaggregated_params: Optional[DisaggregatedParams] = None,
        postproc_params: Optional[PostprocParams] = None,
        multimodal_params: Optional[MultimodalParams] = None,
        scheduling_params: Optional[SchedulingParams] = None,
        cache_salt_id: Optional[int] = None,
    ):
        if isinstance(prompt_token_ids, list):
            self.prompt_token_ids = prompt_token_ids
            self.query_token_ids = query_token_ids
        elif isinstance(prompt_token_ids, (torch.Tensor, np.ndarray)):
            self.prompt_token_ids = prompt_token_ids.tolist()
            if query_token_ids:
                self.query_token_ids = query_token_ids.tolist()
        else:
            raise TypeError(
                f"prompt_token_ids ({prompt_token_ids}) should be an instance of torch.Tensor, np.ndarray or list"
            )

        # NOTE: Exercise caution when adding memory intense attributes, because the current implementation might lead to leaks without manual cleanup.
        # Refer to https://github.com/NVIDIA/TensorRT-LLM/pull/5029#discussion_r2141859873 for details.
        self.sampling_params = sampling_params
        self.postproc_params = postproc_params
        self.lora_request = lora_request
        self.prompt_adapter_request = prompt_adapter_request
        self.streaming = streaming
        self.multimodal_params = multimodal_params
        self.kv_cache_retention_config = kv_cache_retention_config
        self.id: Optional[int] = None
        self.disaggregated_params = disaggregated_params
        self.scheduling_params = scheduling_params
        self.cache_salt_id = cache_salt_id

    def set_id(self, id):
        assert self.id is None, f"Request ID is already set: {self.id}"
        self.id = id
        return self


class CancellingRequest:
    ''' The request to cancel a generation. '''

    def __init__(self, id: int):
        self.id = id

import os

import pytest
from utils.llm_data import llm_models_root
from utils.util import force_ampere, similar

from tensorrt_llm import LLM, SamplingParams
from tensorrt_llm._torch.pyexecutor.llm_request import (LlmRequest,
                                                        SamplingConfig)
from tensorrt_llm.llmapi.llm_utils import KvCacheConfig


@pytest.fixture(scope="module")
def input_prompts():
    return [
        "Born in north-east France, Soyer trained as a",
        "The future of AI is",
    ]


@pytest.fixture(scope="module")
def expected_outputs():
    return {
        "Born in north-east France, Soyer trained as a": [
            "lawyer and was a member of the French Resistance",
            "cook before turning to painting."
        ],
        "The future of AI is": [
            "all about human-machine collaboration.",
            "more promising than you think."
        ],
    }


@pytest.fixture(scope="module")
def llm():
    return LLM(model=os.path.join(llm_models_root(), "llama-models-v2",
                                  "TinyLlama-1.1B-Chat-v1.0"),
               kv_cache_config=KvCacheConfig(max_tokens=1000),
               max_batch_size=8,
               max_seq_len=64,
               disable_overlap_scheduler=True)


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [1, 2, 3])
def test_create_child_request(n: int):
    sampling_config = SamplingConfig()
    setattr(sampling_config, 'top_p', [0.9])
    setattr(sampling_config, 'num_return_sequences', n)

    parent = LlmRequest(
        request_id=1,
        max_new_tokens=10,
        input_tokens=[1, 2, 3],
        sampling_config=sampling_config,
        is_streaming=False,
        client_id=50,
        return_log_probs=True,
        return_context_logits=True,
    )

    for child_id in range(
            parent.request_id + 1,
            parent.request_id + parent.sampling_config.num_return_sequences):
        parent.create_child_request(child_id)

    assert len(parent.child_requests
               ) == parent.sampling_config.num_return_sequences - 1

    for ind, child in enumerate(parent.child_requests):
        assert child.request_id == ind + parent.request_id + 1
        assert child.py_request_id == child.request_id
        assert child.parent_request_id == parent.request_id

        assert child.py_client_id == 50
        assert child.py_max_new_tokens == 10

        assert child.py_return_log_probs == parent.py_return_log_probs
        assert child.py_return_context_logits == parent.py_return_context_logits

        assert child.py_batch_idx is None

        # Verify parent - child independence
        assert child.py_result is not None
        assert child.py_result is not parent.py_result
        assert child.get_tokens() == parent.get_tokens()
        assert child.get_tokens() is not parent.get_tokens()

        assert child.child_requests == []


@force_ampere  # Save H100 resource
@pytest.mark.parametrize("n", [2])
@pytest.mark.parametrize("best_of", [None, 3])
@pytest.mark.threadleak(enabled=False)
def test_n_outputs(n: int, best_of: int, llm, input_prompts, expected_outputs):
    sampling_params = SamplingParams(
        n=n,
        best_of=best_of,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)
    for output_idx, output in enumerate(
            llm.generate(input_prompts, sampling_params=sampling_params)):

        assert len(output.outputs) == n

        for idx, sequence in enumerate(output.outputs):
            if n == best_of:
                assert similar(sequence.text,
                               expected_outputs[input_prompts[output_idx]][idx])


@pytest.mark.parametrize("n", [3])
@pytest.mark.threadleak(enabled=False)
def test_async_n_outputs(n: int, llm, input_prompts):
    sampling_params = SamplingParams(
        n=n,
        temperature=0.8,  # ensure different outputs
        top_p=0.95,  # ensure different outputs
        use_beam_search=False)

    # Asynchronously submit many requests to exceed max batch size.
    futures = []
    for _ in range(5):
        for prompt in input_prompts:
            future = llm.generate_async(prompt, sampling_params)
            futures.append(future)

    # Expect no error raised and each result contains n outputs.
    for _, future in enumerate(futures):
        request_output = future.result()
        assert len(request_output.outputs) == n

