from typing import Optional

from tensorrt_llm.functional import non_gated_version
from tensorrt_llm.models.falcon.model import FalconDecoderLayer
from tensorrt_llm.models.modeling_utils import PretrainedConfig, QuantConfig
from typing_extensions import override

from nemo.export.trt_llm.decoder.decoder import DecoderLayerBuilder, DecoderLayerConfigBuilder
from nemo.export.trt_llm.model_config import (
    LINEAR_COLUMN,
    LINEAR_ROW,
    AttentionConfig,
    LayernormConfig,
    LinearConfig,
    MLPConfig,
)


class FALCONDecoderLayerConfigBuilder(DecoderLayerConfigBuilder):
    """The FALCON implementation of the DecoderLayerConfigBuilder."""

    @override
    def hidden_act_fn(self, layer):
        return layer.mlp.act_fn

    @override
    def infer_num_attention_heads(self, layer):
        return layer.self_attn.num_heads

    @override
    def infer_num_kv_heads(self, layer):
        return layer.self_attn.num_key_value_heads

    @override
    def infer_max_position_embeddings(self, layer):
        return layer.self_attn.max_position_embeddings

    @override
    def build_input_layernorm(self, layer) -> LayernormConfig:
        return LayernormConfig.from_nn_module(layer.input_layernorm, dtype=self.dtype)

    @override
    def build_mlp_layernorm(self, layer) -> LayernormConfig:
        return LayernormConfig.from_nn_module(layer.mlp_layernorm, dtype=self.dtype)

    @override
    def build_attention(self, layer) -> AttentionConfig:
        config = AttentionConfig()
        config.qkv = LinearConfig.from_qkv_nn_modules(
            [layer.self_attn.q_proj, layer.self_attn.k_proj, layer.self_attn.v_proj],
            rank=self.rank,
            tensor_parallel=self.tensor_parallel,
            dtype=self.dtype,
        )

        config.dense = LinearConfig.from_nn_module(
            layer.self_attn.o_proj, LINEAR_ROW, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )

        return config

    @override
    def build_mlp(self, layer) -> MLPConfig:
        config = MLPConfig()
        config.fc = LinearConfig.from_nn_module(
            layer.mlp.gate_proj, LINEAR_COLUMN, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )
        config.proj = LinearConfig.from_nn_module(
            layer.mlp.down_proj, LINEAR_ROW, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )
        config.gate = LinearConfig.from_nn_module(
            layer.mlp.up_proj, LINEAR_COLUMN, rank=self.rank, tensor_parallel=self.tensor_parallel, dtype=self.dtype,
        )

        return config

    @override
    def build_post_layernorm(self, layer) -> Optional[LayernormConfig]:
        return LayernormConfig.from_nn_module(layer.post_attention_layernorm, dtype=self.dtype)


class FALCONDecoderLayerBuilder(DecoderLayerBuilder):
    """The FALCON implementation of the DecoderLayer."""

    @override
    def build_decoder(self, layer):
        # Falcon 7B: parallel_attention=True, new_decoder_architecture=False
        # Falcon 40B/180B: parallel_attention=True, new_decoder_architecture=True
        config = PretrainedConfig(
            architecture=None,
            dtype=self.dtype,
            logits_dtype=self.dtype,
            vocab_size=layer.vocab_size,
            max_position_embeddings=self.max_position_embeddings,
            hidden_size=self.hidden_size,
            num_hidden_layers=self.num_layers,
            num_attention_heads=self.num_attention_heads,
            num_key_value_heads=self.num_kv_heads,
            hidden_act=non_gated_version(self.hidden_act),
            intermediate_size=layer.ffn_hidden_size_local * self.tensor_parallel,
            norm_epsilon=layer.norm_epsilon,
            position_embedding_type="rope_gpt_neox",
            world_size=self.tensor_parallel,
            tp_size=self.tensor_parallel,
            pp_size=1,
            quantization=QuantConfig(),
            max_lora_rank=layer.max_lora_rank,
            use_parallel_embedding=False,
        )

        # No other way to pass in model variant config, determine model variant by num_layers (7B: 32 layers)
        config.set_if_not_exist('new_decoder_architecture', False if self.num_layers == 32 else True)
        config.set_if_not_exist('parallel_attention', True)
        config.set_if_not_exist('layernorm_epsilon', 1e-5)
        config.set_if_not_exist('bias', False)
        config.set_if_not_exist('moe_num_experts', 0)

        return FalconDecoderLayer(config=config, layer_idx=self.layer_id,)

import shutil
from abc import ABC
from enum import Enum
from logging import getLogger
from os import PathLike
from pathlib import Path
from typing import TYPE_CHECKING, Optional, Sequence, Type, Union

from tensorrt_llm.builder import build

from optimum.nvidia.compression.modelopt import ModelOptQuantizer
from optimum.nvidia.export import Workspace
from optimum.nvidia.utils.nvml import get_device_name, is_post_ampere


if TYPE_CHECKING:
    from tensorrt_llm import BuildConfig, Mapping
    from tensorrt_llm.models import PretrainedModel
    from transformers import PreTrainedModel as TransformersPreTrainedModel

    from optimum.nvidia.compression.modelopt import ModelOptRecipe

LOGGER = getLogger()


def infer_plugin_from_build_config(config: "BuildConfig") -> "BuildConfig":
    if is_post_ampere():
        # Required for Chunk Context
        LOGGER.debug("Enabling Paged Context FMHA plugin")
        config.plugin_config.update_from_dict({"use_paged_context_fmha": True})

    config.plugin_config.update_from_dict({"enable_xqa": False})
    return config


class TensorRTArtifactKind(Enum):
    CHECKPOINTS = "checkpoints"
    ENGINES = "engines"


class TensorRTArtifact:
    @staticmethod
    def checkpoints(root: Union[str, PathLike]) -> "TensorRTArtifact":
        return TensorRTArtifact(TensorRTArtifactKind.CHECKPOINTS, root)

    @staticmethod
    def engines(root: Union[str, PathLike]) -> "TensorRTArtifact":
        return TensorRTArtifact(TensorRTArtifactKind.ENGINES, root)

    def __init__(self, kind: TensorRTArtifactKind, root: Union[str, PathLike]):
        self._kind = kind
        self._root = root

    @property
    def kind(self) -> TensorRTArtifactKind:
        return self._kind

    @property
    def root(self) -> Path:
        return Path(self._root)

    def push_to_hub(self):
        raise NotImplementedError()


class TensorRTModelConverter(ABC):
    CONFIG_CLASS: Type
    MODEL_CLASS: Type

    def __init__(
        self,
        model_id: str,
        subpart: str = "",
        workspace: Optional[Union["Workspace", str, bytes, Path]] = None,
        license_path: Optional[Union[str, bytes, Path]] = None,
    ):
        LOGGER.info(f"Creating a model converter for {subpart}")
        if not workspace:
            target_device = get_device_name(0)[-1]
            workspace = Workspace.from_hub_cache(
                model_id, target_device, subpart=subpart
            )

        if isinstance(workspace, (str, bytes, Path)):
            workspace = Workspace(Path(workspace))

        LOGGER.debug(f"Initializing model converter workspace at {workspace.root}")

        self._workspace = workspace
        self._license_path = license_path

    @property
    def workspace(self) -> Workspace:
        return self._workspace

    def save_license(self, licence_filename: str = "LICENSE"):
        """
        Save the license if provided and if the license is not already present.
        This method doesn't check the content of the license
        :param licence_filename: Name of the file containing the license content
        """
        if (
            not (
                dst_licence_file_path := self.workspace.root / licence_filename
            ).exists()
            and self._license_path
        ):
            shutil.copyfile(self._license_path, dst_licence_file_path)

    def quantize(
        self, model: "TransformersPreTrainedModel", qconfig: "ModelOptRecipe"
    ) -> TensorRTArtifact:
        quantizer = ModelOptQuantizer(qconfig)
        quantizer.preprocess_model(model, workspace=self.workspace)
        quantizer.postprocess_model(model, workspace=self.workspace)

        self.save_license()
        return TensorRTArtifact.checkpoints(self._workspace.checkpoints_path)

    def convert(
        self,
        models: Union["PretrainedModel", Sequence["PretrainedModel"]],
        mapping: Optional["Mapping"] = None,
    ) -> TensorRTArtifact:
        """
        Take a local model and create the intermediate TRTLLM checkpoint
        :param models
        :param mapping
        :return:
        """
        if isinstance(models, PretrainedModel):
            models = [models]

        for rank, model in enumerate(models):
            LOGGER.info(
                f"Converting {models[0].config.architecture} model for rank {rank} to TRTLLM"
            )
            model.save_checkpoint(str(self._workspace.checkpoints_path))

        self.save_license()
        return TensorRTArtifact.checkpoints(str(self._workspace.checkpoints_path))

    def build(
        self,
        models: Union["PretrainedModel", Sequence["PretrainedModel"]],
        config: "BuildConfig",
    ) -> TensorRTArtifact:
        """
        :param models
        :param config
        :return:
        """

        if not isinstance(models, Sequence):
            models = [models]

        config = infer_plugin_from_build_config(config)

        for model in models:
            LOGGER.info(
                f"Building TRTLLM engine for rank {model.config.mapping.rank} ->> {config.to_dict()}"
            )

            engine = build(model, config)
            engine.save(str(self._workspace.engines_path))

        self.save_license()
        return TensorRTArtifact.engines(str(self._workspace.engines_path))

