import argparse
import os

import tensorrt_llm
import tensorrt_llm.profiler as profiler
from tensorrt_llm import logger
from tensorrt_llm.runtime import MultimodalModelRunner
from utils import add_common_args


def print_result(model, input_text, output_text, args):
    logger.info("---------------------------------------------------------")
    if model.model_type != "nougat":
        logger.info(f"\n[Q] {input_text}")
    for i in range(len(output_text)):
        logger.info(f"\n[A]: {output_text[i]}")

    if args.num_beams == 1:
        output_ids = model.tokenizer(output_text[0][0], add_special_tokens=False)["input_ids"]
        logger.info(f"Generated {len(output_ids)} tokens")

    if args.check_accuracy and model.model_type != "nougat":
        if model.model_type == "vila":
            for i in range(len(args.image_path.split(args.path_sep))):
                if i % 2 == 0:
                    assert output_text[i][0].lower() == (
                        "the image captures a bustling city intersection teeming with life. "
                        "from the perspective of a car's dashboard camera, we see"
                    )
                else:
                    assert output_text[i][0].lower() == (
                        "the image captures the iconic merlion statue in singapore, "
                        "a renowned worldwide landmark. the merlion, a mythical"
                    )
        elif model.model_type == "llava":
            for i in range(len(args.image_path.split(args.path_sep))):
                assert output_text[i][0].lower() == "singapore"
        elif model.model_type == "fuyu":
            assert output_text[0][0].lower() == "4"
        elif model.model_type == "pix2struct":
            assert (
                "characteristic | cat food, day | cat food, wet | cat treats"
                in output_text[0][0].lower()
            )
        elif model.model_type in ["blip2", "neva", "phi-3-vision", "llava_next"]:
            assert "singapore" in output_text[0][0].lower()
        elif model.model_type == "video-neva":
            assert "robot" in output_text[0][0].lower()
        elif model.model_type == "kosmos-2":
            assert "snowman" in output_text[0][0].lower()
        elif model.model_type == "mllama":
            if "If I had to write a haiku for this one" in input_text:
                assert (
                    "it would be:.\\nPeter Rabbit is a rabbit.\\nHe lives in a" in output_text[0][0]
                    or "Here is a haiku for the image:\n\n" in output_text[0][0]
                ), (
                    f"expected results: 'it would be:.\\nPeter Rabbit is a rabbit.\\nHe lives in a', \
                            generated results: '{output_text[0][0]}'"
                )
            elif "The key to life is" in input_text:
                assert (
                    "to find your passion and pursue it with all your heart." in output_text[0][0]
                    or "not to be found in the external world," in output_text[0][0]
                ), (
                    f"expected results: 'to find your passion and pursue it with all your heart.', \
                            generated results: '{output_text[0][0]}'"
                )
        elif model.model_type == "llava_onevision":
            if args.video_path is None:
                assert "singapore" in output_text[0][0].lower()
            else:
                assert (
                    "the video is funny because the child's actions are"
                    in output_text[0][0].lower()
                )
        elif model.model_type == "qwen2_vl":
            assert "dog" in output_text[0][0].lower()
        else:
            assert output_text[0][0].lower() == "singapore"

    if args.run_profiling:

        def msec_per_batch(name):
            return 1000 * profiler.elapsed_time_in_sec(name) / args.profiling_iterations

        logger.info("Latencies per batch (msec)")
        logger.info("TRT vision encoder: {:.1f}".format(msec_per_batch("Vision")))
        logger.info("TRTLLM LLM generate: {:.1f}".format(msec_per_batch("LLM")))
        logger.info("Multimodal generate: {:.1f}".format(msec_per_batch("Generate")))

    logger.info("---------------------------------------------------------")


if __name__ == "__main__":
    os.environ["TOKENIZERS_PARALLELISM"] = "false"
    parser = argparse.ArgumentParser()
    parser = add_common_args(parser)
    args = parser.parse_args()
    logger.set_level(args.log_level)

    model = MultimodalModelRunner(args)
    input_multimodal_data = model.load_test_data(args.image_path, args.video_path)

    num_iters = args.profiling_iterations if args.run_profiling else 1

    for _ in range(num_iters):
        input_text, output_text = model.run(
            args.input_text, input_multimodal_data, None, args.max_new_tokens
        )

    runtime_rank = tensorrt_llm.mpi_rank()
    if runtime_rank == 0:
        print_result(model, input_text, output_text, args)

import abc
import socket
import sys
import time
from concurrent.futures import Future, ThreadPoolExecutor
from typing import Any, List, Optional

from tensorrt_llm.bindings.BuildInfo import ENABLE_MULTI_DEVICE

if ENABLE_MULTI_DEVICE:
    from mpi4py.futures import MPICommExecutor, MPIPoolExecutor

    from tensorrt_llm._utils import mpi_comm, mpi_rank, mpi_world_size


class MPINodeState:
    ''' MPINodeState acts as a central global state shares between tasks on MPI node.

    An example:
        def task():
            if MPINodeState.state is None:
                MPINodeState.state = 0
            MPINodeState.state += 1
            return MPINodeState.state

        n_workers = 4
        with MPIPoolExecutor(max_workers=n_workers) as executor:
            for i in range(2):
                futures = [executor.submit(task) for i in range(n_workers)]

        This should produce the following output:
        - [1, 1, 1, 1]
        - [2, 2, 2, 2]
    '''

    state = None

    @staticmethod
    def is_initialized() -> bool:
        return MPINodeState.state is not None


def external_mpi_comm_available(model_world_size: int) -> bool:
    ''' Check if the current process is launched by mpirun and does not use MPIPoolExecutor to spawn processes.
    e.g. mpirun -np 4 python script.py
    '''
    if ENABLE_MULTI_DEVICE:
        return mpi_world_size() == model_world_size and model_world_size > 1
    else:
        return False


def need_spawn_mpi_workers(model_world_size: int) -> bool:
    ''' Check if the current process needs to spawn MPI workers. '''
    if ENABLE_MULTI_DEVICE:
        return mpi_world_size() == 1 and model_world_size > 1
    else:
        return False


class MpiSession(abc.ABC):

    @abc.abstractmethod
    def submit(self, task: (...), *args, **kwargs) -> List[Future]:
        raise NotImplementedError()

    @abc.abstractmethod
    def submit_sync(self, task: (...), *args, **kwargs) -> List[Any]:
        raise NotImplementedError()

    @abc.abstractmethod
    def shutdown(self):
        raise NotImplementedError()


class MpiPoolSession(MpiSession):

    def __init__(self, n_workers: int):
        self.n_workers = n_workers
        self.mpi_pool: Optional[MPIPoolExecutor] = None
        self._start_mpi_pool()

    def submit(self, task: (...), *args, **kwargs) -> List[Future]:
        return [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers)
        ]

    def submit_sync(self, task: (...), *args, **kwargs) -> List[Any]:
        futures = [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers)
        ]
        return [future.result() for future in futures]

    def shutdown(self):
        if self.mpi_pool is not None:
            self.mpi_pool.shutdown()
            self.mpi_pool = None

    def _start_mpi_pool(self):
        assert not self.mpi_pool, 'MPI session already started'

        self.mpi_pool = MPIPoolExecutor(max_workers=self.n_workers,
                                        path=sys.path)

    def __del__(self):
        self.shutdown()

    def __reduce__(self):
        raise TypeError('cannot pickle MPI session')


class MpiCommSession(MpiSession):

    def __init__(self, n_workers: int = 1):
        if n_workers <= 0:
            raise ValueError(
                f'n_workers must be non-negative, but got {n_workers}')
        if n_workers != mpi_world_size():
            raise ValueError(
                f'n_workers must be equal to the number of processes launched by mpirun, got {n_workers} vs {mpi_world_size()}'
            )

        if mpi_rank() != 0:
            raise RuntimeError('only rank 0 can start multi-node session')
        if not external_mpi_comm_available(n_workers):
            raise RuntimeError('The LLM instance should be launched by mpirun.')

        self.n_workers = n_workers
        self.thread_pool: Optional[ThreadPoolExecutor] = None
        self.mpi_pool: Optional[MPIPoolExecutor] = None

        self._start_mpi_pool()

    def submit(self, task: (...), *args, **kwargs) -> List[Future]:
        assert self.mpi_pool is not None, 'MPI session not started'

        # Trick: The MPICommExecutor excludes rank0 from workers, thus an extra task dispatching to rank0 is needed
        worker_futures = [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers - 1)
        ]
        # A trick to wait for rank0 to be ready, or the collective tasks will hang
        # TODO[chunweiy]: Remove this trick for reducing normal tasks latencies
        time.sleep(4)

        rank0_future = self.thread_pool.submit(task, *args, **kwargs)
        return [rank0_future] + worker_futures

    def submit_sync(self, task: (...), *args, **kwargs) -> List[Any]:
        futures = self.submit(task, *args, **kwargs)
        return [future.result() for future in futures]

    def shutdown(self):
        if self.mpi_pool is not None:
            self.mpi_pool.shutdown()
            self.mpi_pool = None

    def _start_mpi_pool(self):
        assert not self.mpi_pool, 'MPI session already started'

        self.thread_pool = ThreadPoolExecutor(max_workers=2)
        comm_executor = MPICommExecutor(mpi_comm())
        self.mpi_pool = comm_executor.__enter__()

    def __del__(self):
        self.shutdown()

    def __reduce__(self):
        raise TypeError('cannot pickle MPI session')


def find_free_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind(('', 0))
        return s.getsockname()[1]

