"""Test that the attention matcher works with HF's SDPA backends."""

import copy
from typing import Any, Callable, Dict

import pytest
import torch
import torch.nn as nn
from accelerate import init_empty_weights
from torch.export import Dim
from torch.fx import GraphModule
from transformers.models.llama.configuration_llama import LlamaConfig
from transformers.models.llama.modeling_llama import LlamaModel

from tensorrt_llm._torch.auto_deploy.custom_ops.attention_interface import AttentionDescriptor
from tensorrt_llm._torch.auto_deploy.export import torch_export_to_gm
from tensorrt_llm._torch.auto_deploy.transform.optimizer import InferenceOptimizer
from tensorrt_llm._torch.auto_deploy.transformations._graph import move_to_device

torch.manual_seed(0)


class MockAttentionDescriptor(AttentionDescriptor):
    """A mock class that mimics the AttentionDescriptor interface for testing."""

    layout: str = "bsnd"

    @classmethod
    def get_attention_layout(cls) -> str:
        return cls.layout

    @classmethod
    def get_source_attention_op(cls) -> Callable:
        return torch.ops.auto_deploy.torch_attention_bsnd_grouped_sdpa


class HFWrapper(nn.Module):
    def __init__(self, model: nn.Module):
        super().__init__()
        self.model = model

    @torch.inference_mode()
    def forward(self, x: torch.Tensor):
        return self.model(x)[0]


def _joint_transform(gm: GraphModule) -> None:
    gm = InferenceOptimizer(
        None,
        {
            "match_repeat_kv": {
                "stage": "pattern_matcher",
            },
            "match_eager_attention": {
                "stage": "pattern_matcher",
            },
            "match_grouped_attention": {
                "stage": "pattern_matcher",
            },
            "match_attention_layout": {
                "stage": "pattern_matcher",
                "attention_op": MockAttentionDescriptor,
            },
        },
    )(None, gm)


@pytest.mark.parametrize(
    "config",
    [
        {"num_attention_heads": 8, "num_key_value_heads": 8},
        {"num_attention_heads": 8, "num_key_value_heads": 4},
        {"num_attention_heads": 8, "num_key_value_heads": 1},
    ],
)
@pytest.mark.parametrize(
    "attn_implementation",
    ["eager", "sdpa"],
)
def test_match_llama_attention(config: Dict[str, Any], attn_implementation: str):
    if attn_implementation == "sdpa":
        pytest.skip("https://nvbugspro.nvidia.com/bug/5170222")

    def verify_matcher(gm: GraphModule):
        """Ensure that there is exactly one torch.ops.auto_deploy.torch_attention_bsnd_grouped_sdpa
        call in the graph. Also check that there is no repeat_kv pattern left.
        """
        nodes = gm.graph.find_nodes(
            op="call_function", target=torch.ops.auto_deploy.torch_attention_bsnd_grouped_sdpa
        )
        assert len(nodes) == 1, "Expected exactly one bsnd_grouped_sdpa call in the graph"

        # TODO: check non-qkv args of node
        attn_node = nodes[0]
        scale = model.model.layers[0].self_attn.scaling
        # TODO (lucaslie, #4783): don't check for causal mask until we have more robust handling
        # assert attn_node.args[3:] == (None, 0.0, True, scale), (
        #     "Expected default args for bsnd_grouped_sdpa"
        # )
        assert attn_node.args[4] == 0.0  # dropout_p
        assert attn_node.args[6] == scale  # scale

        # TODO: check that there is no repeat_kv pattern left...
        nodes = gm.graph.find_nodes(
            op="call_function", target=torch.ops.auto_deploy.torch_attention_repeat_kv
        )
        assert len(nodes) == 0, "Found repeat_kv pattern in the graph"
        attn_nodes = gm.graph.find_nodes(
            op="call_function", target=torch.ops.auto_deploy.torch_attention_sdpa
        )
        assert len(attn_nodes) == 0, "Found torch_attention_sdpa node in the graph"

        return True

    batch_size, seq_len = 2, 4
    full_config = {
        "num_hidden_layers": 1,
        "vocab_size": 256,
        "hidden_size": 128,
        "intermediate_size": 128,
        "attn_implementation": attn_implementation,
        **config,
    }
    dynamic_shapes = {0: Dim("batch_size", max=8), 1: Dim("seq_len", min=2, max=8)}

    # Build and export model on meta device
    with init_empty_weights():
        model = HFWrapper(LlamaModel(LlamaConfig(**full_config))).eval()
    x = torch.randint(
        0, full_config["vocab_size"], (batch_size, seq_len), dtype=torch.long, device="cuda"
    )
    gm = torch_export_to_gm(model, args=(x,), dynamic_shapes=(dynamic_shapes,), clone=True)

    print("Exported gm", gm)
    gm_exported = copy.deepcopy(gm)

    # Move model to cuda
    device = "cuda"
    model._apply(
        lambda t: torch.normal(0.0, 1.0, size=t.shape, device=device).to(t.dtype)
        if t.device == torch.device("meta")
        else t.to(device)
    )
    y_model = model(x)

    gm_exported._apply(
        lambda t: torch.normal(0.0, 1.0, size=t.shape, device=device).to(t.dtype)
        if t.device == torch.device("meta")
        else t.to(device)
    )
    gm_exported.load_state_dict(model.state_dict())
    move_to_device(gm_exported, "cuda")
    y_gm_exported = gm_exported(x)
    torch.testing.assert_close(y_gm_exported, y_model, atol=5e-3, rtol=5e-3)

    # Apply transformation
    _joint_transform(gm)
    assert verify_matcher(gm)
    print("Transformed gm", gm)

    # Move gm to cuda
    gm._apply(
        lambda t: torch.normal(0.0, 1.0, size=t.shape, device=device).to(t.dtype)
        if t.device == torch.device("meta")
        else t.to(device)
    )
    gm.load_state_dict(model.state_dict())
    move_to_device(gm, "cuda")

    # Verify output
    y_gm = gm(x)
    torch.testing.assert_close(y_gm_exported, y_gm, atol=5e-2, rtol=5e-2)
    torch.testing.assert_close(y_model, y_gm, atol=5e-2, rtol=5e-2)

from abc import ABC, abstractmethod
from os import getenv

import tensorrt_llm
from tensorrt_llm import logger
from tensorrt_llm._torch.distributed.communicator import Distributed
from tensorrt_llm.bindings import WorldConfig
from tensorrt_llm.bindings.executor import CacheTransceiverConfig
from tensorrt_llm.mapping import Mapping

from .llm_request import LlmRequest
from .resource_manager import KVCacheManager

CacheTransceiverCpp = tensorrt_llm.bindings.internal.batch_manager.CacheTransceiver
AttentionTypeCpp = tensorrt_llm.bindings.internal.batch_manager.AttentionType
CacheTransBufferManagerCpp = tensorrt_llm.bindings.internal.batch_manager.CacheTransBufferManager
BackendTypeCpp = tensorrt_llm.bindings.executor.CacheTransceiverBackendType


def mapping_to_world_config(mapping: Mapping) -> WorldConfig:

    return WorldConfig(tensor_parallelism=mapping.tp_size,
                       pipeline_parallelism=mapping.pp_size,
                       context_parallelism=mapping.cp_size,
                       rank=mapping.rank,
                       gpus_per_node=mapping.gpus_per_node,
                       device_ids=None,
                       enable_attention_dp=mapping.enable_attention_dp)


def create_kv_cache_transceiver(
        mapping: Mapping, dist: Distributed, kv_cache_manager: KVCacheManager,
        attention_type: AttentionTypeCpp,
        cache_transceiver_config: CacheTransceiverConfig):
    if cache_transceiver_config is None or cache_transceiver_config.backend is None:
        logger.info("cache_transceiver is disabled")
        return None

    if cache_transceiver_config.backend == BackendTypeCpp.DEFAULT:
        # When cache_transceiver_config.backend is not set, fallback to env_vars settings
        # UCX is the default backend
        cache_transceiver_config.backend = BackendTypeCpp.UCX
        # Ordered by priority
        env_vars = [("TRTLLM_USE_NIXL_KVCACHE", BackendTypeCpp.NIXL),
                    ("TRTLLM_USE_MPI_KVCACHE", BackendTypeCpp.MPI)]
        for env_var, be_type in env_vars:
            if getenv(env_var) == "1":
                logger.warning(
                    f"{env_var}=1 is set, but it's recommended to set cache_transceiver_config.backend in yaml config"
                )
                cache_transceiver_config.backend = be_type
                break

    if cache_transceiver_config.backend == BackendTypeCpp.MPI:
        logger.warning(
            "MPI CacheTransceiver is deprecated, UCX or NIXL is recommended")
    elif cache_transceiver_config.backend == BackendTypeCpp.UCX:
        logger.info(
            f"Using UCX kv-cache transceiver. If your devices are not in the same domain, please consider setting "
            f"UCX_CUDA_IPC_ENABLE_MNNVL=n, UCX_RNDV_SCHEME=put_zcopy and/or unset UCX_NET_DEVICES upon server "
            f"hangs or lower-than-expected performance.")

    return BindKvCacheTransceiver(mapping, dist, kv_cache_manager,
                                  attention_type, cache_transceiver_config)


class KvCacheTransceiver(ABC):

    @abstractmethod
    def respond_and_send_async(self, req: LlmRequest):
        raise NotImplementedError

    @abstractmethod
    def request_and_receive_sync(self, req: LlmRequest):
        raise NotImplementedError

    @abstractmethod
    def request_and_receive_async(self, req: LlmRequest):
        raise NotImplementedError

    @abstractmethod
    def check_context_transfer_status(self, at_least_request_num: int):
        raise NotImplementedError

    @abstractmethod
    def check_gen_transfer_status(self, at_least_request_num: int):
        raise NotImplementedError

    @abstractmethod
    def check_gen_transfer_complete(self):
        raise NotImplementedError


class BindKvCacheTransceiver(KvCacheTransceiver):

    def __init__(self, mapping: Mapping, dist: Distributed,
                 kv_cache_manager: KVCacheManager,
                 attention_type: AttentionTypeCpp,
                 cache_transceiver_config: CacheTransceiverConfig):
        world_config = mapping_to_world_config(mapping)
        total_num_kv_heads_per_layer = kv_cache_manager.total_num_kv_heads_per_layer
        head_dim = kv_cache_manager.head_dim
        tokens_per_block = kv_cache_manager.tokens_per_block
        dtype = kv_cache_manager.dtype
        # get the layer num per pp rank, which is required by cache transceiver.
        pp_layer_num = len(kv_cache_manager.pp_layers)
        pp_layer_num_per_pp_rank = dist.pp_allgather(pp_layer_num)
        self.impl = CacheTransceiverCpp(kv_cache_manager.impl,
                                        total_num_kv_heads_per_layer, head_dim,
                                        tokens_per_block, world_config,
                                        pp_layer_num_per_pp_rank, dtype,
                                        attention_type,
                                        cache_transceiver_config)

    def respond_and_send_async(self, req: LlmRequest):
        return self.impl.respond_and_send_async(req)

    def request_and_receive_sync(self, req: LlmRequest):
        return self.impl.request_and_receive_sync(req)

    def request_and_receive_async(self, req: LlmRequest):
        return self.impl.request_and_receive_async(req)

    def check_context_transfer_status(self, at_least_request_num: int):
        return self.impl.check_context_transfer_status(at_least_request_num)

    def check_gen_transfer_status(self, at_least_request_num: int):
        return self.impl.check_gen_transfer_status(at_least_request_num)

    def check_gen_transfer_complete(self):
        return self.impl.check_gen_transfer_complete()


class CacheTransBufferManager:

    def __init__(self, kv_cache_manager: KVCacheManager, max_num_tokens: int):
        self.impl = CacheTransBufferManagerCpp(kv_cache_manager.impl,
                                               max_num_tokens)

    @staticmethod
    def pre_alloc_buffer_size(kv_cache_size_per_token: int,
                              cache_transceiver_config: CacheTransceiverConfig):
        return CacheTransBufferManagerCpp.pre_alloc_buffer_size(
            kv_cache_size_per_token, cache_transceiver_config)

