import argparse
import os

from utils import add_common_args, compute_str_match_rate

import tensorrt_llm
import tensorrt_llm.profiler as profiler
from tensorrt_llm import logger
from tensorrt_llm.runtime import MultimodalModelRunner


def print_result(model, input_text, output_text, args):
    logger.info("---------------------------------------------------------")
    if model.model_type != 'nougat':
        logger.info(f"\n[Q] {input_text}")
    for i in range(len(output_text)):
        logger.info(f"\n[A]: {output_text[i]}")

    if args.num_beams == 1:
        output_ids = model.tokenizer(output_text[0][0],
                                     add_special_tokens=False)['input_ids']
        logger.info(f"Generated {len(output_ids)} tokens")

    if args.check_accuracy:
        if model.model_type != 'nougat':
            if model.model_type == "vila":
                for i in range(len(args.image_path.split(args.path_sep))):
                    if i % 2 == 0:
                        assert output_text[i][0].lower(
                        ) == "the image captures a bustling city intersection teeming with life. from the perspective of a car's dashboard camera, we see"
                    else:
                        assert output_text[i][0].lower(
                        ) == "the image captures the iconic merlion statue in singapore, a renowned worldwide landmark. the merlion, a mythical"
            elif model.model_type == "llava":
                for i in range(len(args.image_path.split(args.path_sep))):
                    assert output_text[i][0].lower() == 'singapore'
            elif model.model_type == 'fuyu':
                assert output_text[0][0].lower() == '4'
            elif model.model_type == "pix2struct":
                assert "characteristic | cat food, day | cat food, wet | cat treats" in output_text[
                    0][0].lower()
            elif model.model_type in [
                    'blip2', 'neva', 'phi-3-vision', 'llava_next',
                    'phi-4-multimodal', 'pixtral'
            ]:
                assert 'singapore' in output_text[0][0].lower()
            elif model.model_type == 'video-neva':
                assert 'robot' in output_text[0][0].lower()
            elif model.model_type == 'kosmos-2':
                assert 'snowman' in output_text[0][0].lower()
            elif model.model_type == "mllama":
                if "If I had to write a haiku for this one" in input_text:
                    ref_1 = ", it would be:.\\nPeter Rabbit is a rabbit.\\nHe lives in a cozy little house.\\nHe's a very good rabbit.\\"
                    ref_2 = "Here is a haiku for the image:\n\n"

                elif "Answer:" in input_text:
                    ref_1 = "2,173. <OCR/> A 1 2 3 4 5 6 Date Income 2005-12-17"
                    ref_2 = "Answer: 2,173. <OCR/> 1 2 3 4 5 6 Date Income 2005-12-17"

                elif "The key to life is" in input_text:
                    ref_1 = "to find your passion and pursue it with all your heart. For me, that passion is photography. I love capturing the beauty of the world around me"
                    ref_2 = "not to be found in the external world,"
                output = output_text[0][0]
                match_rate = max(compute_str_match_rate(ref_1, output),
                                 compute_str_match_rate(ref_2, output))
                logger.info(f"match rate: {match_rate}")
                assert match_rate >= 50, \
                    f"expected results: '{ref_1}' or '{ref_2}', generated results: '{output}'"

            elif model.model_type == 'llava_onevision':
                if args.video_path is None:
                    assert 'singapore' in output_text[0][0].lower()
                else:
                    assert 'the video is funny because the child\'s actions are' in output_text[
                        0][0].lower()
            elif model.model_type == "qwen2_vl":
                assert 'dog' in output_text[0][0].lower()
            else:
                assert output_text[0][0].lower() == 'singapore'

    if args.run_profiling:
        msec_per_batch = lambda name: 1000 * profiler.elapsed_time_in_sec(
            name) / args.profiling_iterations
        logger.info('Latencies per batch (msec)')
        logger.info('e2e generation: %.1f' % (msec_per_batch('Generate')))
        logger.info(' ' * 2 + 'Preprocessing: %.1f' %
                    (msec_per_batch('Preprocess')))
        logger.info(' ' * 4 + 'Vision encoder: %.1f' %
                    (msec_per_batch('Vision encoder')))
        if profiler.elapsed_time_in_sec('Feature transform') is not None:
            logger.info(' ' * 4 + 'Feature transform: %.1f' %
                        (msec_per_batch('Feature transform')))
        logger.info(' ' * 2 + 'LLM generate: %.1f' % (msec_per_batch('LLM')))
        logger.info(' ' * 2 + 'Tokenizer decode: %.1f' %
                    (msec_per_batch('Tokenizer decode')))

    logger.info("---------------------------------------------------------")


if __name__ == '__main__':
    os.environ["TOKENIZERS_PARALLELISM"] = "false"
    parser = argparse.ArgumentParser()
    parser = add_common_args(parser)
    args = parser.parse_args()
    logger.set_level(args.log_level)

    model = MultimodalModelRunner(args)
    visual_data = model.load_test_data(args.image_path, args.video_path)
    audio_data = model.load_test_audio(args.audio_path)

    if args.run_profiling:
        num_warmup_iters = 3  # Multiple iterations to load both vision and LLM engines into memory
        for _ in range(num_warmup_iters):
            input_text, output_text = model.run(args.input_text, visual_data,
                                                audio_data, args.max_new_tokens)
        profiler.reset()

    num_iters = args.profiling_iterations if args.run_profiling else 1

    for _ in range(num_iters):
        input_text, output_text = model.run(args.input_text, visual_data,
                                            audio_data, args.max_new_tokens)

    runtime_rank = tensorrt_llm.mpi_rank()
    if runtime_rank == 0:
        print_result(model, input_text, output_text, args)

# TODO: raise error if VILA mode 1 with C++ runtime

import abc
import socket
import sys
import time
from collections.abc import Callable
from concurrent.futures import Future, ThreadPoolExecutor
from typing import List, Optional, TypeVar

from tensorrt_llm.bindings.BuildInfo import ENABLE_MULTI_DEVICE

if ENABLE_MULTI_DEVICE:
    from mpi4py.futures import MPICommExecutor, MPIPoolExecutor

    from tensorrt_llm._utils import mpi_comm, mpi_rank, mpi_world_size

T = TypeVar("T")


class MPINodeState:
    ''' MPINodeState acts as a central global state shares between tasks on MPI node.

    An example:
        def task():
            if MPINodeState.state is None:
                MPINodeState.state = 0
            MPINodeState.state += 1
            return MPINodeState.state

        n_workers = 4
        with MPIPoolExecutor(max_workers=n_workers) as executor:
            for i in range(2):
                futures = [executor.submit(task) for i in range(n_workers)]

        This should produce the following output:
        - [1, 1, 1, 1]
        - [2, 2, 2, 2]
    '''

    state = None

    @staticmethod
    def is_initialized() -> bool:
        return MPINodeState.state is not None


def external_mpi_comm_available(model_world_size: int) -> bool:
    ''' Check if the current process is launched by mpirun and does not use MPIPoolExecutor to spawn processes.
    e.g. mpirun -np 4 python script.py
    '''
    if ENABLE_MULTI_DEVICE:
        return mpi_world_size() == model_world_size and model_world_size > 1
    else:
        return False


def need_spawn_mpi_workers(model_world_size: int) -> bool:
    ''' Check if the current process needs to spawn MPI workers. '''
    if ENABLE_MULTI_DEVICE:
        return mpi_world_size() == 1 and model_world_size > 1
    else:
        return False


class MpiSession(abc.ABC):

    @abc.abstractmethod
    def submit(self, task: Callable[..., T], *args,
               **kwargs) -> List[Future[T]]:
        raise NotImplementedError()

    @abc.abstractmethod
    def submit_sync(self, task: Callable[..., T], *args, **kwargs) -> List[T]:
        raise NotImplementedError()

    @abc.abstractmethod
    def shutdown(self):
        raise NotImplementedError()


class MpiPoolSession(MpiSession):

    def __init__(self, n_workers: int):
        self.n_workers = n_workers
        self.mpi_pool: Optional[MPIPoolExecutor] = None
        self._start_mpi_pool()

    def submit(self, task: Callable[..., T], *args,
               **kwargs) -> List[Future[T]]:
        return [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers)
        ]

    def submit_sync(self, task: Callable[..., T], *args, **kwargs) -> List[T]:
        futures = [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers)
        ]
        return [future.result() for future in futures]

    def shutdown(self):
        if self.mpi_pool is not None:
            self.mpi_pool.shutdown(wait=False)
            self.mpi_pool = None

    def _start_mpi_pool(self):
        assert not self.mpi_pool, 'MPI session already started'

        self.mpi_pool = MPIPoolExecutor(max_workers=self.n_workers,
                                        path=sys.path)

    def __del__(self):
        self.shutdown()

    def __reduce__(self):
        raise TypeError('cannot pickle MPI session')


class MpiCommSession(MpiSession):

    def __init__(self, n_workers: int = 1):
        if n_workers <= 0:
            raise ValueError(
                f'n_workers must be non-negative, but got {n_workers}')
        if n_workers != mpi_world_size():
            raise ValueError(
                f'n_workers must be equal to the number of processes launched by mpirun, got {n_workers} vs {mpi_world_size()}'
            )

        if mpi_rank() != 0:
            raise RuntimeError(
                f'only rank 0 can start multi-node session, got {mpi_rank()}')
        if not external_mpi_comm_available(n_workers):
            raise RuntimeError('The LLM instance should be launched by mpirun.')

        self.n_workers = n_workers
        self.thread_pool: Optional[ThreadPoolExecutor] = None
        self.mpi_pool: Optional[MPIPoolExecutor] = None

        self._start_mpi_pool()

    def submit(self,
               task: (...),
               rank0_extra_kwargs: Optional[dict] = None,
               *args,
               **kwargs) -> List[Future]:
        ''' Submit a task to MPI workers.

        Args:
            task: The task to be submitted.
            rank0_extra_kwargs: Extra keyword arguments for rank0 task.
            args: Positional arguments for the task.
            kwargs: Keyword arguments for the task.
        '''
        assert self.mpi_pool is not None, 'MPI session not started'
        # Trick: The MPICommExecutor excludes rank0 from workers, thus an extra
        # task dispatching to rank0 is needed
        rank0_extra_kwargs = rank0_extra_kwargs or {}

        rank0_params = kwargs.copy()
        if rank0_extra_kwargs:
            rank0_params.update(rank0_extra_kwargs)

        worker_futures = [
            self.mpi_pool.submit(task, *args, **kwargs)
            for i in range(self.n_workers - 1)
        ]

        # A trick to wait for rank0 to be ready, or the collective tasks will hang
        # TODO[chunweiy]: Remove this trick
        time.sleep(10)

        rank0_future = self.thread_pool.submit(task, *args, **rank0_params)
        return [rank0_future] + worker_futures

    def submit_sync(self, task: Callable[..., T], *args, **kwargs) -> List[T]:
        futures = self.submit(task, *args, **kwargs)
        return [future.result() for future in futures]

    def shutdown(self):
        if self.mpi_pool is not None:
            self.mpi_pool.shutdown(wait=False)
            self.mpi_pool = None

    def _start_mpi_pool(self):
        assert not self.mpi_pool, 'MPI session already started'

        self.thread_pool = ThreadPoolExecutor(max_workers=2)
        comm_executor = MPICommExecutor(mpi_comm())
        self.mpi_pool = comm_executor.__enter__()

    def __del__(self):
        self.shutdown()

    def __reduce__(self):
        raise TypeError('cannot pickle MPI session')


def find_free_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind(('', 0))
        return s.getsockname()[1]

from abc import ABC, abstractmethod
from typing import Callable, List, Union

from torch import nn

from tensorrt_llm._torch.model_config import ModelConfig
from tensorrt_llm._torch.models.modeling_utils import DecoderModelForCausalLM


class BaseWeightMapper(ABC):

    def __init__(self):
        self._callbacks: list[Callable] = []
        self._mapping: dict = {}
        self._skip_modules = []
        self._model: Union[nn.Module, DecoderModelForCausalLM] | None = None
        self._config: ModelConfig | None = None

    def init_model_and_config(self, model: Union[nn.Module,
                                                 DecoderModelForCausalLM],
                              config: ModelConfig):
        self._model = model
        self._config = config

        if not hasattr(model, 'model_config') or not isinstance(
                model.model_config, ModelConfig):
            raise ValueError("model must have a model_config attribute")
        if not hasattr(model, 'config'):
            raise ValueError("model must have a config attribute")

        self._tp_size = 1 if model.model_config.mapping.enable_attention_dp else model.model_config.mapping.tp_size
        self._head_dim = model.config.head_dim if hasattr(
            model.config, 'head_dim'
        ) and model.config.head_dim is not None else model.config.hidden_size // model.config.num_attention_heads

        self.map_weights()

    def cleanup(self) -> None:
        self._model = None
        self._config = None

    @abstractmethod
    def map_weights(self) -> None:
        """
        Maps weights from TRT-LLM to a source state dictionary (e.g., Hugging Face)
        """

    @abstractmethod
    def apply_callbacks(self, module: nn.Module, module_name: str,
                        module_names_breakdown: list[str],
                        weights: dict) -> list[dict]:
        """
        Applies a series of transformation functions to an internal representation
        of weights or to guide the mapping process. The exact behavior might depend
        on the implementation (e.g., storing callbacks to be applied later).

        Args:
            module: The module to apply the callbacks to
            module_name: The specific module name (e.g., 'qkv_proj', 'gate_up_proj')
            module_names_breakdown: List of module path components for building full paths
            weights: The weights dictionary to process
        """

    def rename_by_params_map(self, params_map: dict[str, str],
                             weights: dict) -> dict:
        """
        Rename weight keys according to regex pattern matching.

        Args:
            pattern_mapping: A dictionary mapping regex patterns to replacement strings. The key is HF name pattern, and the value is corresponding TRT-LLM name pattern.
                The patterns will be used to match keys in the weights dict and replace
                them according to the replacement string, which can use regex backreferences.
                Example:
                HF name: vision_model.encoder.layers.1.self_attn.out_proj.{weight,bias}
                TRT-LLM name: vision_model.encoder.layers.1.self_attn.o_proj.{weight,bias}
                Then the pattern_mapping could be:
                pattern_mapping = {
                    r'(.*?)out_proj(.*)': r'\1o_proj\2'
                }
            weights: A dictionary of weights

        Returns:
            A dictionary of weights with renamed keys
        """
        import re

        # Create a new dictionary to store the renamed weights
        renamed_weights = {}

        # Keep track of keys that have been matched by a pattern
        matched_keys = set()

        # Process each key in the weights dictionary
        for key in list(weights.keys()):
            # Check each pattern for a match
            for pattern, replacement in params_map.items():
                if re.match(pattern, key):
                    # Create the new key by applying the regex replacement
                    new_key = re.sub(pattern, replacement, key)
                    # Store the weight with the new key
                    renamed_weights[new_key] = weights[key]
                    matched_keys.add(key)
                    break

            # If the key wasn't matched by any pattern, keep it as is
            if key not in matched_keys:
                renamed_weights[key] = weights[key]

        return renamed_weights

    def preprocess_weights(self, weights: dict) -> dict:
        """
        Preprocess weights before starting the loading process.
        """
        ...

    def handle_manual_copy(self, module_name: str, module_weights: dict, n: str,
                           p: nn.Parameter) -> None:
        p.data.copy_(module_weights[n][:])

    def does_require_special_handling(self, module_name: str) -> bool:
        return module_name in self.mapping

    def is_special_instance_module(self, module: nn.Module) -> bool:
        return False

    def handle_special_instance_module(self, module: nn.Module,
                                       module_name: str,
                                       module_weights: dict) -> None:
        raise NotImplementedError()

    @property
    def skip_modules(self) -> List[str]:
        return self._skip_modules

    def add_skip_modules(self, value: List[str]) -> None:
        self._skip_modules.extend(value)

    def should_skip_module(self, module_name: str) -> bool:
        return any(skip_module in module_name
                   for skip_module in self._skip_modules)

    def filter_weights(self, prefix: str, weights: dict) -> dict:
        result = {}
        for k, v in weights.items():
            if k.startswith(prefix):
                new_k = k[len(prefix) + 1:]
                result[new_k] = v
        return result

    @property
    def mapping(self) -> dict:
        return self._mapping

    @property
    def config(self) -> ModelConfig:
        if self._config is None:
            raise RuntimeError("Weight mapper is not initialized")
        return self._config

    @property
    def model(self) -> Union[nn.Module, DecoderModelForCausalLM]:
        if self._model is None:
            raise RuntimeError("Weight mapper is not initialized")
        return self._model

