import os
import sys
import glob
import logging
import numpy as np

from .. import ops, timer
from .runtime import Runtime

logger = logging.getLogger(__name__)

class TensorRTLLMBertRuntime(Runtime):
    def __init__(self, path, ** kwargs):
        import torch
        import tensorrt as trt
        
        self.stream = torch.cuda.Stream().cuda_stream
        
        super().__init__(path, ** kwargs)

        self._dtype_mapping   = {
            trt.DataType.BF16   : 'bfloat16',
            
            trt.DataType.BOOL   : 'bool',
            
            trt.DataType.FLOAT  : 'float32',
            trt.DataType.HALF   : 'float16',
            
            trt.DataType.INT8   : 'int8',
            trt.DataType.INT32  : 'int32',
            trt.DataType.INT64  : 'int64',
            trt.DataType.UINT8  : 'uint8'
        }
        
        self.device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        
        self.bindings   = list(self.engine.engine)
        self._inputs    = tuple(
            n for n in self.bindings if self.engine.engine.get_tensor_mode(n) == trt.TensorIOMode.INPUT
        )
        self._outputs   = tuple(
            n for n in self.bindings if self.engine.engine.get_tensor_mode(n) == trt.TensorIOMode.OUTPUT
        )
        self._dtypes    = tuple(
            self._dtype_mapping[self.engine.engine.get_tensor_dtype(n)] for n in self.bindings
        )
        self._shapes    = tuple(
            self.engine.engine.get_tensor_shape(n) for n in self.bindings
        )
        self._var_shapes    = set([
            n for n in self._inputs if any(s == -1 for s in self.engine.engine.get_tensor_shape(n))
        ])
        
        self.sos_token  = -1
        self.eos_token  = -1
        self.pad_token  = -1
    
    def set_tokens(self, sos_token = None, eos_token = None, pad_token = None):
        if sos_token not in (-1, None): self.sos_token = sos_token
        if eos_token not in (-1, None): self.eos_token = eos_token
        if pad_token not in (-1, None): self.pad_token = pad_token
    
    @property
    def remove_input_padding(self):
        return len(self.shapes[0]) == 1
    
    @property
    def embedding_dim(self):
        return self.shapes[-1][-1]
    
    @property
    def argnames(self):
        return self._inputs
    
    @property
    def outputs(self):
        return self._outputs

    @property
    def dtypes(self):
        return self._dtypes
    
    @property
    def shapes(self):
        return self._shapes
    
    def __repr__(self):
        return '<TensorRTLLMBertRuntime path={} inputs={} outputs={}>'.format(
            os.path.basename(self.path), self.argnames, self.outputs
        )
    
    @timer(name = 'TensorRTLLM runtime inference')
    def __call__(self, inputs, ** _):
        import torch
        import tensorrt as trt
        
        from tensorrt_llm.runtime import TensorInfo
        
        _is_batch = _is_batched(inputs)
        if not _is_batch: inputs = [inputs]
        
        if self.remove_input_padding:
            tokens, lengths, pos_ids = [], [], []
            for inp in inputs:
                tokens.extend(inp)
                lengths.append(len(inp))
                pos_ids.extend(range(2, len(inp) + 2))
            
            tokens = torch.tensor(np.array(tokens), dtype = torch.int32, device = self.device)
        else:
            if len(inputs) > 1:
                tokens = [
                    torch.tensor(np.array(tok), dtype = torch.int32, device = 'cpu')
                    for tok in inputs
                ]
                tokens = torch.nn.utils.rnn.pad_sequence(
                    tokens, batch_first = True, padding_value = self.pad_token
                ).to(device = self.device)
            else:
                tokens = torch.tensor(np.array(inputs), dtype = torch.int32, device = self.device)
            lengths = [len(inp) for inp in inputs]
            pos_ids = np.array([np.arange(2, tokens.shape[1] + 2)] * len(inputs))
            
        
        inputs  = {
            'input_ids' : tokens,
            'input_lengths' : torch.tensor(np.array(lengths), dtype = torch.int32, device = self.device),
            'token_type_ids'    : torch.zeros_like(tokens)
        }
        if self.remove_input_padding:
            inputs.update({
                'position_ids'  : torch.tensor(pos_ids, dtype = torch.int32, device = self.device),
                'max_input_length'  : torch.tensor(
                    [max(lengths)], dtype = torch.int32, device = self.device
                )
            })

        output_infos = self.engine.infer_shapes([
            TensorInfo(k, trt.DataType.INT32, v.shape) for k, v in inputs.items()
        ])
        outputs = {
            i.name : torch.zeros(
                * i.shape, dtype = getattr(torch, self._dtype_mapping[i.dtype]), device = self.device
            )
            for i in output_infos
        }

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug('Calling TensorRTLLM engine with :\n  Inputs : {}\n  Outputs : {}'.format(
                {name : tuple(v.shape) for name, v in inputs.items()},
                {name : tuple(v.shape) for name, v in outputs.items()}
            ))

        if not self.engine.run(inputs, outputs, self.stream):
            raise RuntimeError('An exception occured while running the TensorRT context')

        if _is_batch and self.remove_input_padding:
            outputs = {k : list(torch.split(v, lengths)) for k, v in outputs.items()}

        torch.cuda.synchronize()
        
        return outputs if len(outputs) > 1 else list(outputs.values())[0]
    
    @staticmethod
    def prepare_tensor(tensor, device):
        return ops.convert_to_torch_tensor(tensor, dtype = 'int32').to(device = device)
    
    @staticmethod
    def load_engine(path, ** _):
        from tensorrt_llm.runtime import Session
        
        engine_path = glob.glob(os.path.join(path, '*.engine'))[0]
        
        logger.info('Loading engine from {}'.format(engine_path))
        
        with open(engine_path, 'rb') as f:
            engine_buffer = f.read()
        
        session = Session.from_serialized_engine(engine_buffer)
        
        return session

def _is_batched(inputs):
    return isinstance(inputs, list) and len(ops.shape(inputs[0])) == 1

#!/usr/bin/env python3
import os
import subprocess  # nosec B404
import tempfile
from pathlib import Path

import click

from tensorrt_llm.hlapi import ModelConfig
from tensorrt_llm.hlapi._perf_evaluator import LLMPerfEvaluator
from tensorrt_llm.hlapi.llm import ModelLoader, _ModelFormatKind
from tensorrt_llm.hlapi.utils import print_colored

try:
    from .grid_searcher import GridSearcher
except:
    from grid_searcher import GridSearcher


@click.group()
def cli():
    pass


@click.command("benchmark")
@click.option("--model-path", type=str, required=True)
@click.option("--samples-path", type=str, required=True)
@click.option("--report-path-prefix", type=str, required=True)
@click.option("--num-samples", type=int, default=-1)
@click.option("--tp-size", type=int, default=1, show_default=True)
@click.option("--warmup", type=int, default=100, show_default=True)
@click.option("--max-num-tokens", type=int, default=2048, show_default=True)
@click.option("--max-input-length", type=int, required=True, default=200)
@click.option("--max-output-length", type=int, required=True, default=200)
@click.option("--max-batch-size", type=int, default=128)
@click.option("--engine-output-dir", type=str, default="")
@click.option(
    "--cpp-executable",
    type=str,
    default=None,
    help="Path to the cpp executable, set it if you want to run the cpp benchmark"
)
@click.option("--enable-executor", is_flag=True, default=False)
def benchmark_main(model_path: str,
                   samples_path: str,
                   report_path_prefix: str,
                   num_samples: int = -1,
                   tp_size: int = 1,
                   warmup: int = 100,
                   max_num_tokens=2048,
                   max_input_length: int = 200,
                   max_output_length: int = 200,
                   max_batch_size: int = 128,
                   engine_output_dir: str = "",
                   cpp_executable: str = None,
                   enable_executor: bool = False):
    ''' Run the benchmark on HLAPI.
    If `cpp_executable_path` is provided, it will run the cpp benchmark as well.
    '''
    model_path = Path(model_path)
    samples_path = Path(samples_path)
    if not model_path.exists():
        raise FileNotFoundError(f"Model path {model_path} not found")
    if not samples_path.exists():
        raise FileNotFoundError(f"Samples path {samples_path} not found")

    engine_output_dir = engine_output_dir or None
    temp_dir = None
    if engine_output_dir:
        engine_output_dir = Path(engine_output_dir)
    elif cpp_executable:
        if ModelLoader.get_model_format(
                model_path) is _ModelFormatKind.TLLM_ENGINE:
            engine_output_dir = model_path
        else:
            temp_dir = tempfile.TemporaryDirectory()
            engine_output_dir = Path(temp_dir.name)

    def run_hlapi():
        print_colored(f"Running HLAPI benchmark ...\n", "bold_green")

        config = ModelConfig(model_path)
        config._set_additional_options(
            max_num_tokens=max_num_tokens,
            max_input_len=max_input_length,
            max_output_len=max_output_length,
            max_batch_size=max_batch_size,
        )
        config.parallel_config.tp_size = tp_size

        evaluator = LLMPerfEvaluator.create(
            config,
            num_samples=num_samples,
            samples_path=samples_path,
            warmup=warmup,
            engine_cache_path=engine_output_dir,
            # The options should be identical to the cpp benchmark
            use_custom_all_reduce=True,
            enable_chunked_context=False,
            # additional options to LLM
            enable_executor=enable_executor,
        )
        assert evaluator
        report = evaluator.run()
        report.display()

        report_path = Path(report_path_prefix + ".json")
        if report_path.exists():
            for i in range(10000):
                if (Path(f"report_path_prefix{i}.json").exists()):
                    continue
                else:
                    report_path = Path(f"report_path_prefix{i}")
                    break

        report.save_json(report_path)

    def run_gpt_manager_benchmark():
        print_colored(f"Running gptManagerBenchmark ...\n", "bold_green")
        cpp_executable_path = (
            cpp_executable and cpp_executable != "on") or os.path.join(
                os.path.dirname(__file__),
                "../../cpp/build/benchmarks/gptManagerBenchmark")

        run_command = f"{cpp_executable_path} --engine_dir {engine_output_dir} --type IFB --dataset {samples_path} --warm_up {warmup} --output_csv {report_path_prefix}.cpp.csv"
        if enable_executor:
            run_command += " --api executor"
        launch_prefix = f"mpirun -n {tp_size}" if tp_size > 1 else ""
        command = f"{launch_prefix} {run_command}"
        output = subprocess.run(command,
                                check=True,
                                universal_newlines=True,
                                shell=True,
                                capture_output=True,
                                env=os.environ)  # nosec B603
        print_colored(f'cpp benchmark output: {output.stdout}', "grey")
        print(f'cpp benchmark error: {output.stderr}', "red")

    run_hlapi()
    if cpp_executable:
        run_gpt_manager_benchmark()


@click.command("gridsearch")
@click.option("--model-path", type=str, required=True)
@click.option("--samples-path", type=str, required=True)
@click.option("--reports-root", type=str, required=True)
@click.option("--prune-space-for-debug",
              type=int,
              default=1e8,
              help="Specify the first N cases to test")
@click.option("--max-input-len", type=int, default=1024)
@click.option("--max-output-len", type=int, default=1024)
@click.option("--max-num-tokens", type=int, default=4096)
@click.option("--tp-size", type=int, default=1)
@click.option("--num-samples", type=int, default=200)
def grid_searcher_main(model_path,
                       samples_path,
                       reports_root,
                       prune_space_for_debug: int,
                       max_input_len: int,
                       max_output_len: int,
                       max_num_tokens: int,
                       tp_size: int = 1,
                       num_samples: int = 200):
    reports_root = Path(reports_root)

    grid_searcher = GridSearcher(prune_space_for_debug=prune_space_for_debug, )

    model_config = ModelConfig(model_path)
    model_config.parallel_config.tp_size = tp_size

    model_config._set_additional_options(max_output_len=max_input_len,
                                         max_input_len=max_output_len,
                                         max_num_tokens=max_num_tokens)

    grid_searcher.evaluate(
        model_config=model_config,
        samples_path=samples_path,
        report_dir=reports_root,
        memory_monitor_interval=1,
        num_samples=num_samples,
    )


if __name__ == '__main__':
    cli.add_command(benchmark_main)
    cli.add_command(grid_searcher_main)
    cli()

from abc import ABC, abstractmethod
from typing import Optional, Set, Type

import pytest
import torch
import torch.nn as nn
import torch.nn.functional as F
from _model_test_utils import MLP
from _torch_test_utils import all_close
from torch.export import Dim, export
from torch.fx import GraphModule

from tensorrt_llm._torch.auto_deploy.export import torch_export_to_gm


def _torch_export_non_strict(model, *args, **kwargs):
    kwargs["strict"] = False
    return export(model, *args, **kwargs)


class ModuleForExport(ABC, nn.Module):
    @abstractmethod
    def forward(self, x):
        pass

    @abstractmethod
    def get_sample_input(self):
        pass

    def check_xfail(self, f_export, use_dynamic_shape, device) -> bool:
        return False

    @abstractmethod
    def get_dynamic_shapes(self):
        pass


class MLPForExport(ModuleForExport):
    def __init__(self):
        super().__init__()
        self.mlp = MLP(10, 10, 10)

    def forward(self, x):
        return self.mlp(x)

    def get_sample_input(self):
        return torch.randn(2, 10)

    def get_dynamic_shapes(self):
        return {0: Dim("batch_size", max=100)}


class MLPDuplicate(ModuleForExport):
    def __init__(self, device: Optional[str] = None):
        super(MLPDuplicate, self).__init__()
        self.fc1 = nn.Linear(10, 10)
        self.fc2 = nn.Linear(10, 10)
        self.fc3 = nn.Linear(10, 10)
        self.to(device)
        self.fc3.weight = self.fc1.weight

    def forward(self, x):
        x = self.fc1(x)
        x = self.fc2(x)
        x = self.fc3(x)
        return x

    def get_sample_input(self):
        return torch.randn(2, 10, device=self.fc1.weight.device)

    def get_deduplicated_keys(self) -> Set[str]:
        return {"fc3.weight"}

    def get_dynamic_shapes(self):
        return {0: Dim("batch_size", max=100)}


class ModuleWithWhere(ModuleForExport):
    def where(self, mask):
        return torch.where(mask)

    def forward(self, x):
        is_positive = x > 0
        output = torch.zeros_like(x)
        idx1, idx2 = self.where(is_positive)
        output[idx1, idx2] = x[idx1, idx2]
        return output

    def get_sample_input(self):
        return torch.randn(2, 10)

    def get_dynamic_shapes(self):
        return {0: Dim("batch_size", max=100)}

    def check_xfail(self, f_export, use_dynamic_shape, device) -> bool:
        return (
            use_dynamic_shape and f_export in [export, _torch_export_non_strict]
        ) or device == "meta"


class ModuleWithNonzero(ModuleWithWhere):
    def where(self, mask):
        return torch.nonzero(mask, as_tuple=True)

    def check_xfail(self, f_export, use_dynamic_shape, device):
        return device == "meta"


class ModuleWithRouting(ModuleForExport):
    def __init__(self):
        super().__init__()
        self.num_experts = 8
        self.seq_len = 32
        self.top_k = 2

    def forward(self, x):
        _, selected_experts = torch.topk(x, self.top_k, dim=-1)
        expert_mask = F.one_hot(selected_experts, self.num_experts).permute(2, 1, 0)
        out = torch.zeros_like(x)

        for idx_e in range(self.num_experts):
            _, top_x = torch.where(expert_mask[idx_e])

            out[top_x] += x[top_x]

            return out

    def get_sample_input(self):
        return torch.randn(self.seq_len, self.num_experts)

    def get_dynamic_shapes(self):
        return {0: Dim("seq_len", max=100)}

    def check_xfail(self, f_export, use_dynamic_shape, device) -> bool:
        return (
            use_dynamic_shape and f_export in [export, _torch_export_non_strict]
        ) or device == "meta"


class ModuleWithModuleList(ModuleForExport):
    def __init__(self, device: Optional[str] = None, num_active_layers: int = 2):
        super().__init__()
        self.fcs = nn.ModuleList([nn.Linear(10, 10) for _ in range(4)])
        self.num_active_layers = num_active_layers
        self.to(device)

    def forward(self, x):
        for fc in self.fcs[: self.num_active_layers]:
            x = fc(x)
        return x

    def get_sample_input(self):
        return torch.randn(2, 10, device=self.fcs[0].weight.device)

    def get_dynamic_shapes(self):
        return {0: Dim("batch_size", max=100)}

    def check_xfail(self, f_export, use_dynamic_shape, device) -> bool:
        # non-strict mode only works with our hack in torch_export_to_gm
        return f_export in [_torch_export_non_strict]


@pytest.mark.parametrize(
    "f_export",
    [torch.export.export, export, _torch_export_non_strict, torch_export_to_gm],
)
@pytest.mark.parametrize("use_dynamic_shape", [True, False])
@pytest.mark.parametrize("device", ["cpu", "cuda", "meta"])
@pytest.mark.parametrize(
    "mod_cls",
    [
        MLPForExport,
        MLPDuplicate,
        ModuleWithWhere,
        ModuleWithNonzero,
        ModuleWithRouting,
        ModuleWithModuleList,
    ],
)
def test_module_export(f_export, mod_cls, device, use_dynamic_shape):
    mod = mod_cls().to(device)
    if mod.check_xfail(f_export, use_dynamic_shape, device):
        pytest.xfail(
            f"{mod_cls.__name__} expected to fail with: {f_export.__name__}, "
            f"use_dynamic_shape={use_dynamic_shape}, device={device}"
        )

    x = mod.get_sample_input().to(device)

    # run export now
    if use_dynamic_shape:
        dynamic_shapes = mod.get_dynamic_shapes()
        ep = f_export(mod, (x,), dynamic_shapes=(dynamic_shapes,))
    else:
        ep = f_export(mod, (x,))

    if not isinstance(ep, GraphModule):
        ep = ep.module()

    y = mod(x)
    y_ep = ep(x)

    if device != "meta":
        assert all_close(y, y_ep)

    print(ep.graph)


@pytest.mark.parametrize("model_cls", [MLPDuplicate])
@pytest.mark.parametrize("device_export", ["cpu"])  # TODO: investigate meta device error
def test_deduplicate_during_export(model_cls: Type[nn.Module], device_export: str):
    model = model_cls(device=device_export)
    model.eval()
    t_in = model.get_sample_input()

    # run export now
    gm = torch_export_to_gm(model, (t_in,))

    # check that deduplicated keys are removed from state_dict
    assert gm.state_dict().keys() == model.state_dict().keys() - model.get_deduplicated_keys()

    def check_parameter_loading(param_to_pop: str, expected_param: str):
        """Helper function to check parameter loading behavior.

        Args:
            param_to_pop: The parameter to remove from state dict before loading
            expected_param: The parameter whose value should be loaded into fc1.weight
        """
        sd_og = model.state_dict()
        sd_og.pop(param_to_pop)
        gm.load_state_dict(sd_og)

        if device_export != "meta":
            assert torch.equal(gm.fc1.weight, sd_og[expected_param])

    # fc3.weight is aliased to fc1.weight
    # Test loading fc3.weight into gm.fc1.weight. State dict does not contain fc1.weight
    check_parameter_loading("fc1.weight", "fc3.weight")

    # Test loading fc1.weight into gm.fc1.weight. State dict does not contain fc3.weight
    check_parameter_loading("fc3.weight", "fc1.weight")

