import os
import sys
import glob
import logging
import numpy as np

from .. import ops, timer
from .runtime import Runtime

logger = logging.getLogger(__name__)

class TensorRTLLMBertRuntime(Runtime):
    def __init__(self, path, ** kwargs):
        import torch
        import tensorrt as trt
        
        self.stream = torch.cuda.Stream().cuda_stream
        
        super().__init__(path, ** kwargs)

        self._dtype_mapping   = {
            trt.DataType.BF16   : 'bfloat16',
            
            trt.DataType.BOOL   : 'bool',
            
            trt.DataType.FLOAT  : 'float32',
            trt.DataType.HALF   : 'float16',
            
            trt.DataType.INT8   : 'int8',
            trt.DataType.INT32  : 'int32',
            trt.DataType.INT64  : 'int64',
            trt.DataType.UINT8  : 'uint8'
        }
        
        self.device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
        
        self.bindings   = list(self.engine.engine)
        self._inputs    = tuple(
            n for n in self.bindings if self.engine.engine.get_tensor_mode(n) == trt.TensorIOMode.INPUT
        )
        self._outputs   = tuple(
            n for n in self.bindings if self.engine.engine.get_tensor_mode(n) == trt.TensorIOMode.OUTPUT
        )
        self._dtypes    = tuple(
            self._dtype_mapping[self.engine.engine.get_tensor_dtype(n)] for n in self.bindings
        )
        self._shapes    = tuple(
            self.engine.engine.get_tensor_shape(n) for n in self.bindings
        )
        self._var_shapes    = set([
            n for n in self._inputs if any(s == -1 for s in self.engine.engine.get_tensor_shape(n))
        ])
        
        self.sos_token  = -1
        self.eos_token  = -1
        self.pad_token  = -1
    
    def set_tokens(self, sos_token = None, eos_token = None, pad_token = None):
        if sos_token not in (-1, None): self.sos_token = sos_token
        if eos_token not in (-1, None): self.eos_token = eos_token
        if pad_token not in (-1, None): self.pad_token = pad_token
    
    @property
    def remove_input_padding(self):
        return len(self.shapes[0]) == 1
    
    @property
    def embedding_dim(self):
        return self.shapes[-1][-1]
    
    @property
    def argnames(self):
        return self._inputs
    
    @property
    def outputs(self):
        return self._outputs

    @property
    def dtypes(self):
        return self._dtypes
    
    @property
    def shapes(self):
        return self._shapes
    
    def __repr__(self):
        return '<TensorRTLLMBertRuntime path={} inputs={} outputs={}>'.format(
            os.path.basename(self.path), self.argnames, self.outputs
        )
    
    @timer(name = 'TensorRTLLM runtime inference')
    def __call__(self, inputs, ** _):
        import torch
        import tensorrt as trt
        
        from tensorrt_llm.runtime import TensorInfo
        
        _is_batch = _is_batched(inputs)
        if not _is_batch: inputs = [inputs]
        
        if self.remove_input_padding:
            tokens, lengths, pos_ids = [], [], []
            for inp in inputs:
                tokens.extend(inp)
                lengths.append(len(inp))
                pos_ids.extend(range(2, len(inp) + 2))
            
            tokens = torch.tensor(np.array(tokens), dtype = torch.int32, device = self.device)
        else:
            if len(inputs) > 1:
                tokens = [
                    torch.tensor(np.array(tok), dtype = torch.int32, device = 'cpu')
                    for tok in inputs
                ]
                tokens = torch.nn.utils.rnn.pad_sequence(
                    tokens, batch_first = True, padding_value = self.pad_token
                ).to(device = self.device)
            else:
                tokens = torch.tensor(np.array(inputs), dtype = torch.int32, device = self.device)
            lengths = [len(inp) for inp in inputs]
            pos_ids = np.array([np.arange(2, tokens.shape[1] + 2)] * len(inputs))
            
        
        inputs  = {
            'input_ids' : tokens,
            'input_lengths' : torch.tensor(np.array(lengths), dtype = torch.int32, device = self.device),
            'token_type_ids'    : torch.zeros_like(tokens)
        }
        if self.remove_input_padding:
            inputs.update({
                'position_ids'  : torch.tensor(pos_ids, dtype = torch.int32, device = self.device),
                'max_input_length'  : torch.tensor(
                    [max(lengths)], dtype = torch.int32, device = self.device
                )
            })

        output_infos = self.engine.infer_shapes([
            TensorInfo(k, trt.DataType.INT32, v.shape) for k, v in inputs.items()
        ])
        outputs = {
            i.name : torch.zeros(
                * i.shape, dtype = getattr(torch, self._dtype_mapping[i.dtype]), device = self.device
            )
            for i in output_infos
        }

        if logger.isEnabledFor(logging.DEBUG):
            logger.debug('Calling TensorRTLLM engine with :\n  Inputs : {}\n  Outputs : {}'.format(
                {name : tuple(v.shape) for name, v in inputs.items()},
                {name : tuple(v.shape) for name, v in outputs.items()}
            ))

        if not self.engine.run(inputs, outputs, self.stream):
            raise RuntimeError('An exception occured while running the TensorRT context')

        if _is_batch and self.remove_input_padding:
            outputs = {k : list(torch.split(v, lengths)) for k, v in outputs.items()}

        torch.cuda.synchronize()
        
        return outputs if len(outputs) > 1 else list(outputs.values())[0]
    
    @staticmethod
    def prepare_tensor(tensor, device):
        return ops.convert_to_torch_tensor(tensor, dtype = 'int32').to(device = device)
    
    @staticmethod
    def load_engine(path, ** _):
        from tensorrt_llm.runtime import Session
        
        engine_path = glob.glob(os.path.join(path, '*.engine'))[0]
        
        logger.info('Loading engine from {}'.format(engine_path))
        
        with open(engine_path, 'rb') as f:
            engine_buffer = f.read()
        
        session = Session.from_serialized_engine(engine_buffer)
        
        return session

def _is_batched(inputs):
    return isinstance(inputs, list) and len(ops.shape(inputs[0])) == 1

from functools import partial
from typing import (Any, Callable, Coroutine, Dict, Iterable, List, Literal,
                    Optional, Tuple, TypeAlias, TypedDict, Union, cast)

from openai.types.chat import (ChatCompletionContentPartImageParam,
                               ChatCompletionContentPartInputAudioParam)
from openai.types.chat import \
    ChatCompletionContentPartParam as OpenAIChatCompletionContentPartParam
from openai.types.chat import (ChatCompletionContentPartTextParam,
                               ChatCompletionMessageParam)
from transformers import AutoConfig
from typing_extensions import Required

from tensorrt_llm.inputs import (ConversationMessage, MultimodalData,
                                 MultimodalDataTracker,
                                 add_multimodal_placeholders, async_load_audio,
                                 async_load_image, async_load_video)
from tensorrt_llm.logger import logger


class VideoURL(TypedDict):
    """Type definition for video URL structure."""
    url: Required[str]


class ChatCompletionContentPartVideoParam(TypedDict, total=False):
    """Type definition for video content part parameters."""
    video_url: Required[VideoURL]
    type: Required[Literal["video_url"]]


# Type Aliases and Constants
ChatCompletionContentPartParam: TypeAlias = Union[
    OpenAIChatCompletionContentPartParam, ChatCompletionContentPartVideoParam,
    str]

# TODO: Add "input_audio" to support byte_encoded audio input.
VALID_MESSAGE_CONTENT_MM_PART_TYPES = [
    "text", "image_url", "video_url", "audio_url"
]

# Parser Functions
_TextParser = partial(cast, ChatCompletionContentPartTextParam)
_ImageParser = partial(cast, ChatCompletionContentPartImageParam)
_VideoParser = partial(cast, ChatCompletionContentPartVideoParam)
_AudioParser = partial(cast, ChatCompletionContentPartInputAudioParam)

MM_PARSER_MAP: dict[str, Callable[[ChatCompletionContentPartParam], Union[
    str, dict[str, str]]]] = {
        "text":
        lambda part: _TextParser(part).get("text", None),
        "image_url":
        lambda part: _ImageParser(part).get("image_url", {}).get("url", None),
        "video_url":
        lambda part: _VideoParser(part).get("video_url", {}).get("url", None),
        "audio_url":
        lambda part: _AudioParser(part).get("audio_url", {}).get("url", None),
    }


def _parse_chat_message_content_mm_part(
    part: ChatCompletionContentPartParam
) -> tuple[str, Union[str, dict[str, str]]]:
    """Parse a single multimodal part of a chat message."""
    assert isinstance(part, dict)
    part_type = part.get("type", None)

    if isinstance(part_type, str) and part_type in MM_PARSER_MAP:
        return part_type, MM_PARSER_MAP[part_type](part)

    if not isinstance(part_type, str):
        raise ValueError("Invalid 'type' field in multimodal part.")
    return part_type, "unknown part_type content"


def parse_chat_message_content_part(
    part: ChatCompletionMessageParam, ) -> Optional[Any]:
    """Parse a single part of a chat message."""
    if isinstance(part, str):
        return part

    part_type, content = _parse_chat_message_content_mm_part(part)

    # if part_type is text/image_url/video_url/audio_url but content is None, log a warning and skip
    if part_type in VALID_MESSAGE_CONTENT_MM_PART_TYPES and content is None:
        logger.warning(
            "Skipping multimodal part '%s' (type: '%s') with empty / unparsable content.",
            part, part_type)
        return None

    if part_type == "text":
        return cast(str, content)

    if part_type == "image_url":
        str_content = cast(str, content)

        async def load_image_async():
            try:
                return await async_load_image(str_content)
            except Exception as e:
                logger.error(f"Failed to load image: {str(e)}")
                return None

        return MultimodalData(modality="image", data=load_image_async())

    if part_type == "video_url":
        str_content = cast(str, content)

        async def load_video_async():
            try:
                return await async_load_video(str_content, num_frames=8)
            except Exception as e:
                logger.error(f"Failed to load video: {str(e)}")
                return None

        return MultimodalData(modality="video", data=load_video_async())

    if part_type == "audio_url":
        str_content = cast(str, content)

        async def load_audio_async():
            try:
                return await async_load_audio(str_content)
            except Exception as e:
                logger.error(f"Failed to load audio: {str(e)}")
                return None

        return MultimodalData(modality="audio", data=load_audio_async())

    raise NotImplementedError(f"Unknown part type: {part_type}")


def parse_chat_message_content_parts(
    role: str,
    parts: Iterable[ChatCompletionMessageParam],
) -> ConversationMessage:
    """Parse multiple parts of a chat message."""
    text_parts = []
    media_parts = []
    for part in parts:
        parse_res = parse_chat_message_content_part(part)
        if parse_res:
            if isinstance(parse_res, str):
                text_parts.append(parse_res)
            else:
                media_parts.append(parse_res)

    text_prompt = "\n".join(text_parts)

    return ConversationMessage(role=role,
                               content=text_prompt,
                               media=media_parts)


def parse_chat_message_content(
    message: ChatCompletionMessageParam, ) -> ConversationMessage:
    """Parse the content of a chat message."""
    role = message["role"]
    content = message.get("content")

    if content is None:
        content = []
    elif isinstance(content, str):
        content = [
            ChatCompletionContentPartTextParam(type="text", text=content)
        ]

    result = parse_chat_message_content_parts(
        role,
        content,
    )
    return result


def parse_chat_messages_coroutines(
    messages: List[ChatCompletionMessageParam],
    model_config: AutoConfig,
) -> Tuple[List[ConversationMessage], Optional[Coroutine[
        Any, Any, Optional[Dict[str, List[Any]]]]]]:
    """Parse multiple chat messages and return conversation and coroutine."""
    conversation = []
    mm_placeholder_counts = []
    mm_data_tracker = MultimodalDataTracker(model_config.model_type)

    for msg in messages:
        parsed_msg = parse_chat_message_content(msg)
        conversation.append(parsed_msg)
        if parsed_msg["media"]:
            for mdata in parsed_msg["media"]:
                mm_data_tracker.add_data(mdata["modality"], mdata["data"])
        mm_placeholder_count = mm_data_tracker.placeholder_counts()
        if mm_placeholder_count:
            parsed_msg["content"] = add_multimodal_placeholders(
                model_config.model_type, parsed_msg["content"],
                mm_placeholder_count)
        mm_placeholder_counts.append(mm_placeholder_count)

    return conversation, mm_data_tracker.retrieve_all_async(
    ), mm_placeholder_counts


def check_multiple_response(n: int, backend: Optional[str]):
    if n > 1 and backend == "pytorch":
        raise ValueError(
            "Multiple response is not supported in PyTorch workflow")

