import concurrent.futures
import json
import os
import random
import re
import sys

import numpy
import torch
from filelock import FileLock
from PIL import Image

from via_logger import TimeMeasure


class NVila:

    def __init__(self, model_path, max_batch_size=None, use_trt=False, **kwargs) -> None:
        self._model = None
        self._max_batch_size = max_batch_size
        self._inflight_req_ids = []
        self._use_trt = use_trt

        if bool(os.environ.get("NVILA_USE_PYTORCH", "")):
            self._use_trt = False

        if self._use_trt:
            # TRT Model
            with TimeMeasure("VILA TRT model load"):
                # Load the TRT model
                import tensorrt_llm.bindings
                from tensorrt_llm._torch import LLM

                if "NVILA_VIDEO_MAX_TILES" not in os.environ:
                    os.environ["NVILA_VIDEO_MAX_TILES"] = "4"

                with FileLock(model_path + "/.lock"):
                    self._llm = LLM(
                        model=model_path,
                        kv_cache_config=tensorrt_llm.bindings.executor.KvCacheConfig(
                            free_gpu_memory_fraction=float(
                                os.environ.get("TRT_LLM_MEM_USAGE_FRACTION", "") or 0.4
                            )
                        ),
                    )
        else:
            sys.path.append(os.path.dirname(__file__) + "/VILA")
            import llava
            from llava import conversation as clib

            self._model = llava.load(model_path)
            clib.default_conversation = clib.conv_templates["auto"].copy()
            if os.environ.get("NVILA_VIDEO_MAX_TILES"):
                self._model.config.video_max_tiles = int(os.environ.get("NVILA_VIDEO_MAX_TILES"))
                self._model.llm.config.video_max_tiles = int(
                    os.environ.get("NVILA_VIDEO_MAX_TILES")
                )

        self._output_tpool = concurrent.futures.ThreadPoolExecutor(max_workers=max_batch_size)

        self.model_path = model_path

        with open(os.path.join(model_path, "config.json"), "r") as f:
            self._model_config = json.load(f)
            self._num_time_tokens = self._model_config.get("num_time_tokens", 0)

    @property
    def model_name(self):
        return self._model_name

    def get_conv(self):
        return self._conv.copy()

    def _postprocess(self, output, video_frames_times):
        with TimeMeasure("TRT generate"):
            output.result()
            self._inflight_req_ids.remove(output)
        result = output.outputs[0].text
        if video_frames_times:
            for i, t in enumerate(video_frames_times):
                result = re.sub(f"T{i}(?![0-9])", t, result)
                result = re.sub(f"t{i}(?![0-9])", t, result)
                excess_pattern = re.compile(r"<t(\d+)>")
                matches = excess_pattern.findall(result)
                for match in matches:
                    t = int(match)
                    if t >= len(video_frames_times):
                        result = result.replace(f"<t{t}>", f"<{video_frames_times[-1]}>")
        return [result], [{"input_tokens": 0, "output_tokens": output.outputs[0].length}]

    def can_enqueue_requests(self):
        return len(self._inflight_req_ids) < self._max_batch_size

    def warmup(self):
        self.generate("Say Hi", [torch.ones(100, 100, 3).cuda()])

    @property
    def num_time_tokens(self):
        return self._num_time_tokens

    def generate(self, prompt, images, generation_config=None, video_frames_times=None):
        """Generate a response for prompt using the video embeddings

        Args:
            prompt: Conversation prompt
            video_embeds: Batch of video embeddings
            video_frames_times: Batch of video frame times used for embeddings for each chunk
            generation_config: VLM generation config. Defaults to None.

        Returns:
            List of responses for the batch of chunks
        """

        # Populate default values for the VLM generation parameters
        if not generation_config:
            generation_config = {}

        if "temperature" not in generation_config:
            generation_config["temperature"] = 0.4

        if generation_config["temperature"] == 0:
            generation_config.pop("temperature")

        if "max_new_tokens" not in generation_config:
            generation_config["max_new_tokens"] = 512

        if "top_p" not in generation_config:
            generation_config["top_p"] = 1

        if "top_k" not in generation_config:
            generation_config["top_k"] = 100
        generation_config["top_k"] = int(generation_config["top_k"])

        if "seed" in generation_config:
            seed = generation_config["seed"]
            generation_config.pop("seed")
        else:
            seed = 1

        # Set the seed
        random.seed(seed)
        numpy.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

        if self._use_trt:

            from tensorrt_llm import SamplingParams

            input = {
                "prompt": "<vila/video>" + prompt,
                "multi_modal_data": {
                    "video": [[torch.permute(image, (2, 0, 1)).half().div(255) for image in images]]
                },
            }

            # TRT mode
            output = self._llm.generate_async(
                inputs=input,
                sampling_params=SamplingParams(
                    max_tokens=generation_config.pop("max_new_tokens"),
                    **generation_config,
                    seed=seed,
                ),
            )

            self._inflight_req_ids.append(output)

            return self._output_tpool.submit(
                self._postprocess,
                output,
                video_frames_times,
            )
        else:
            images = [Image.fromarray(image.cpu().detach().numpy()) for image in images]
            media = {"video": [images]}
            gen_config = self._model.default_generation_config
            gen_config.update(**generation_config)
            result = self._model.generate_content(
                "<vila/video>" + prompt, media=media, generation_config=gen_config
            )
            if video_frames_times:
                for i, t in enumerate(video_frames_times):
                    result = re.sub(f"T{i}(?![0-9])", t, result)
            return [result], [{"input_tokens": 0, "output_tokens": 0}]

    @staticmethod
    def get_model_info():
        return "nvila", "internal", "NVIDIA"

import os
from abc import ABC, abstractmethod
from typing import Optional

import numpy as np
import torch
import torch.distributed as dist

from tensorrt_llm._utils import (mpi_allgather, mpi_barrier, mpi_broadcast,
                                 mpi_comm, mpi_isend, mpi_isend_object,
                                 mpi_recv, mpi_recv_object, mpi_send,
                                 mpi_send_object)
from tensorrt_llm.mapping import Mapping


class Distributed(ABC):

    def __init__(self, mapping: Mapping):
        self.mapping = mapping

    @property
    def rank(self):
        return self.mapping.rank

    @property
    def world_size(self):
        return self.mapping.world_size

    @property
    def has_tp(self):
        return self.mapping.has_tp()

    @property
    def has_pp(self):
        return self.mapping.has_pp()

    @property
    def cp_size(self):
        return self.mapping.cp_size

    @property
    def pp_size(self):
        return self.mapping.pp_size

    @property
    def tp_size(self):
        return self.mapping.tp_size

    @property
    def cp_rank(self):
        return self.mapping.cp_rank

    @property
    def tp_rank(self):
        return self.mapping.tp_rank

    @property
    def pp_rank(self):
        return self.mapping.pp_rank

    @property
    def is_last_pp_rank(self):
        return self.mapping.is_last_pp_rank()

    @property
    def is_second_last_pp_rank(self):
        return self.mapping.is_second_last_pp_rank()

    @property
    def is_first_pp_rank(self):
        return self.mapping.is_first_pp_rank()

    @property
    def next_pp_rank(self):
        return self.mapping.next_pp_rank()

    @property
    def prev_pp_rank(self):
        return self.mapping.prev_pp_rank()

    @property
    def has_cp(self):
        return self.mapping.has_cp()

    @property
    def cp_config(self):
        return self.mapping.cp_config

    @abstractmethod
    def broadcast(self, obj, root=0):
        pass

    @abstractmethod
    def allgather(self, obj, root=0):
        pass


class MPIDist(Distributed):

    def __init__(self, mapping: Mapping):
        super().__init__(mapping)
        self.create_tp_comm()
        self.create_pp_comm()

    def broadcast(self, obj, root=0):
        return mpi_broadcast(obj, root)

    def allgather(self, obj):
        return mpi_allgather(obj)

    def barrier(self):
        mpi_barrier()

    def isend(self, buf: np.ndarray, dest, tag=0):
        # non-blocking send numpy buffer
        return mpi_isend(buf, dest, tag)

    def send(self, buf: np.ndarray, dest, tag=0):
        # blocking send numpy buffer
        mpi_send(buf, dest, tag)

    def recv(self, buf: np.ndarray, src, tag=0):
        # in-place recv numpy buffer
        return mpi_recv(buf, src, tag)

    def send_object(self, obj, dest, tag=0):
        mpi_send_object(obj, dest, tag)

    def isend_object(self, obj, dest, tag=0):
        return mpi_isend_object(obj, dest, tag)

    def recv_object(self, src, tag=0):
        return mpi_recv_object(src, tag)

    def create_tp_comm(self):
        new_group = mpi_comm().group.Incl(self.mapping.tp_group)
        self.tp_comm = mpi_comm().Create_group(new_group)

    def create_pp_comm(self):
        new_group = mpi_comm().group.Incl(self.mapping.pp_group)
        self.pp_comm = mpi_comm().Create_group(new_group)

    def tp_allgather(self, obj):
        return self.tp_comm.allgather(obj)

    def tp_gather(self, obj):
        return self.tp_comm.gather(obj)

    def tp_broadcast(self, obj, root=0):
        return self.tp_comm.bcast(obj, root)

    def pp_allgather(self, obj):
        return self.pp_comm.allgather(obj)

    def pp_gather(self, obj):
        return self.pp_comm.gather(obj)

    def pp_broadcast(self, obj, root=0):
        return self.pp_comm.bcast(obj, root)


class TorchDist(Distributed):

    def __init__(self, mapping: Mapping):
        super().__init__(mapping)
        if not dist.is_initialized():
            master_ip = os.getenv("MASTER_ADDR", "localhost")
            # TODO: fix the constant default port
            master_port = os.getenv("MASTER_PORT", "6000")
            init_method = f"tcp://{master_ip}:{master_port}"
            dist.init_process_group(backend="nccl",
                                    init_method=init_method,
                                    world_size=mapping.world_size,
                                    rank=mapping.rank)
        self.device_tp_group = dist.new_group(mapping.tp_group, backend="nccl")
        self.cpu_tp_group = dist.new_group(mapping.tp_group, backend="gloo")
        self.device_cp_group = dist.new_group(mapping.cp_group, backend="nccl")
        self.cpu_cp_group = dist.new_group(mapping.cp_group, backend="gloo")

    def broadcast_tp(self, obj, root=0):
        if root not in self.mapping.tp_group:
            return obj
        elif self.rank == root:
            torch.distributed.broadcast_object_list([obj],
                                                    src=root,
                                                    group=self.cpu_tp_group)
            return obj
        else:
            recv = [None]
            torch.distributed.broadcast_object_list(recv,
                                                    src=root,
                                                    group=self.cpu_tp_group)
            return recv[0]

    def broadcast_cp(self, obj, root=0):
        if root not in self.mapping.cp_group:
            return obj
        elif self.rank == root:
            torch.distributed.broadcast_object_list([obj],
                                                    src=root,
                                                    group=self.cpu_cp_group)
            return obj
        else:
            recv = [None]
            torch.distributed.broadcast_object_list(recv,
                                                    src=root,
                                                    group=self.cpu_cp_group)
            return recv[0]

    def broadcast(self, obj, root=0):
        assert not (self.mapping.has_cp()
                    and self.mapping.has_tp()), 'unsupport mix cp and tp now'
        if self.mapping.has_cp():
            self.broadcast_cp(obj, root)
        elif self.mapping.has_tp():
            self.broadcast_tp(obj, root)
        else:
            pass


class PPComm:

    def __init__(self, global_mapping: Mapping):
        self.mapping = global_mapping
        self.nccl_comm = torch.classes.trtllm.NcclCommunicatorOp(
            self.mapping.world_size,
            self.mapping.rank,
        )

    def send(self, tensor: torch.Tensor, dest: Optional[int] = None):
        if dest is None:
            dest = self.mapping.next_pp_rank()
        self.nccl_comm.send(tensor, dest)

    def recv(self, tensor: torch.Tensor, src: Optional[int] = None):
        if src is None:
            src = self.mapping.prev_pp_rank()
        self.nccl_comm.recv(tensor, src)


_pp_comm = None


def init_pp_comm(mapping):
    """Initialize PPComm once at startup"""
    global _pp_comm
    _pp_comm = PPComm(mapping)


def pp_recv(tensor):
    """Receive tensors from previous pp rank."""
    _pp_comm.recv(tensor)


def pp_send(tensor):
    """Send tensors to next pp rank."""
    _pp_comm.send(tensor)

